/* ÇEVİRİ id · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("id","olay",{
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1266-01-01:0":{"b": ["Setelah wafatnya Algu, Mübârek Şah diproklamasikan sebagai khan, khan Chagatai pertama yang memeluk Islam", "dbc13140"], "d": ["Ketika Algu (1260-1266), pendiri sesungguhnya Kekhanan Chagatai, meninggal pada 1266, Mübârek Şah, putra Ergene Hatun, diproklamasikan sebagai khan; ia adalah penguasa pertama di antara keturunan Chagatai yang memeluk Islam.", "47499084"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1275-01-01:0":{"b": ["Ismailiyah berusaha merebut kembali Alamut; Mongol memukul mundur mereka", "8ffd690c"], "d": ["Setelah Hülâgû menghancurkan Alamut pada 1256, Ismailiyah mengerahkan diri untuk menduduki kembali benteng itu tetapi dipukul mundur oleh bangsa Mongol (1275).", "4bb7e566"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0697-01-01:0":{"b": ["Venesia memilih doge pertamanya: Paulo Lucio Anafesto", "b57d289e"], "d": ["Menurut kisahnya, komunitas laguna yang bergantung pada Bizantium memilih Paulo Lucio Anafesto sebagai doge pertama atas kehendak sendiri pada 697; awal politik Republik Venesia dikaitkan dengan tahun ini.", "a3e027cb"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0812-01-01:0":{"b": ["Markgrafat Toskana (Tuscia) Karoling didirikan: Bonifacio dari Bayern menjadi comte Lucca", "fddd5c9f"], "d": ["Markgrafat Toskana (Tuscia), yang lahir sebagai lembaga militer dan politik pada masa Karoling, sebagai kelanjutan kadipaten Lombard Lucca diberikan kepada Bonifacio dari Bayern dalam bentuk kecomtean pada 812 (Bonifacio 812-23). Pada paruh kedua abad ke-9 comte Lucca, Adalberto I (845-98), menjadi markgraf Tuscia; pada pertengahan abad ke-11 markgrafat berpindah kepada para penguasa Canossa, yaitu Attoni.", "5c965bec"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0862-01-01:0":{"b": ["Bangsa Varangia diundang ke Novgorod di bawah pimpinan Rurik: awal wangsa Rurik", "65189ade"], "d": ["Suku-suku Slavia dan Finlandia mengusir bangsa Varangia (Rus) pada 859, tetapi setelah berselisih di antara mereka sendiri, tiga tahun kemudian (862) mereka memanggil kembali bangsa itu; tiga bersaudara Rurik, Sineus, dan Truvor menerima undangan tersebut. Ibu kota Rurik adalah Novgorod di tepi Sungai Volkhov; dinasti para knyaz Rus berasal dari sini.", "92237ec5"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0863-01-01:0":{"b": ["Atas undangan Rastislav, Kirilus dan Metodius datang ke Moravia; bangsa Moravia dikristenkan", "032e458e"], "d": ["Sebagai hasil persekutuan Moravia Raya dengan Bizantium untuk melawan pengaruh Frank, dua biarawan Yunani, Kirilus dan Metodius, yang dikirim dari Konstantinopel, datang ke Moravia pada 863 dan meletakkan dasar liturgi Slavia.", "b11b9057"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0872-01-01:0":{"b": ["Harald Hårfagre menyatukan Norwegia melalui Pertempuran Hafrsfjord (tradisional 872)", "c3fc7edf"], "d": ["Menurut tradisi, Harald Hårfagre mengalahkan para saingannya dalam Pertempuran Hafrsfjord pada 872 dan menjadi raja pertama Norwegia; namun SNL menilainya hanya sebagai penulisan sejarah yang baru terbentuk kemudian (abad ke-12), dan menempatkan masa pemerintahan Harald dari sekitar 865 hingga 930-933.", "33a5f0b2"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0882-01-01:0":{"b": ["Oleg turun dari Novgorod ke selatan dan merebut Kiev; wangsa Rurik berdiri di Kiev", "68d6c7b5"], "d": ["Oleg, penerus pertama dinasti yang didirikan bangsa Varangia (Rus) di sekitar Rurik, bergerak dari Novgorod ke selatan, menduduki Kiev, dan memperluas kekuasaannya ke Rusia selatan; dengan peristiwa ini inti Kiev Rus terbentuk.", "73585f4e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0894-01-01:0":{"b": ["Raja Moravia Raya Svatopluk wafat", "bed9da30"], "d": ["Svatopluk, yang setelah menggulingkan Rastislav dan menyerahkannya kepada bangsa Frank memperluas Moravia dari Oder hingga Gran, wafat pada 894; perselisihan antara putra-putranya pun dimulai dan serbuan Magyar membawa keruntuhan negara itu.", "7c153526"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0895-01-01:0":{"b": ["Suku-suku Magyar di bawah pimpinan Árpád melintasi Karpatia dan menetap di Lembah Karpatia (895-896)", "dcccb96b"], "d": ["Suku-suku Magyar di bawah pimpinan Árpád melintasi Karpatia pada 895-896 dan menjadikan Transilvania serta Dataran Besar sebagai tanah air; sekitar 900 mereka menyebar hingga seberang Danube (Pannonia). Setelah pemukiman itu, Moravia Raya runtuh.", "2427d9dd"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0907-01-01:0":{"b": ["Ekspedisi Oleg ke Konstantinopel: pasukan Rus mencapai ibu kota Bizantium", "f8a401e9"], "d": ["Ekspedisi Oleg ke Konstantinopel; pasukan Rus mencapai ibu kota Bizantium (Kronik Utama 907).", "6143a74b"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0911-01-01:0":{"b": ["Perjanjian dagang dan perdamaian dibuat antara Oleg dan Bizantium", "1ac7641f"], "d": ["Perjanjian dagang dan perdamaian dibuat antara Oleg dan Bizantium.", "58e2b923"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0930-01-01:0":{"b": ["Althing pertama Islandia bersidang di Þingvellir", "1218d81c"], "d": ["Althing, yang menurut tradisi didirikan sekitar 930, adalah majelis nasional dan badan peradilan Islandia; menurut tradisi, pada Althing pertama diterima 'Ulvljots-lovene' yang berdasarkan contoh Gulatingsloven, dan juru bicara hukum pertama (lovsigemann) Ravn Høngsson dipilih. Masa Landnám (pemukiman) berlangsung sekitar 870-930.", "bdf71f7d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0935-09-28:0":{"b": ["Adipati Bohemia, Santo Wenceslas, dibunuh oleh saudaranya Boleslav", "338efe2c"], "d": ["Wenceslas, sekutu Jerman, dibunuh oleh tangan saudaranya Boleslav pada 935 (kemudian dinyatakan sebagai santo); pembunuhan ini memicu perang dengan Jerman. Pada masa Boleslav dan putranya Boleslav II, Bohemia memperluas perbatasannya hingga Moravia, Silesia, dan Galisia.", "ea71d5bf"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0947-01-01:0":{"b": ["Hasan bin Ali al-Kalbi menjadi gubernur Sisilia: Emirat Kalbi dimulai", "4490a575"], "d": ["Khalifah Fatimiyah al-Mansur Billah mengangkat Hasan bin Ali al-Kalbi sebagai gubernur Sisilia untuk menumpas Pemberontakan Bani Tabari (335/947); pengangkatan ini membuka masa Kalbi yang memerintah semi-merdeka selama sembilan puluh tahun.", "ab7351cf"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0953-01-01:0":{"b": ["Hasan al-Kalbi pergi menemui Khalifah Muiz dan menjadi panglima tertinggi; putranya Ahmad tinggal sebagai wakil di Palermo", "3f35b587"], "d": ["Hasan al-Kalbi pergi menemui khalifah baru, Muiz, dan menjadi panglima tertingginya; ia meninggalkan putranya Ahmad sebagai wakil di Sisilia.", "e9218520"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0955-08-10:0":{"b": ["Lechfeld: serbuan Magyar berakhir dengan kekalahan dari Raja Jerman Otto I", "11535e07"], "d": ["Setelah kekalahan di Lechfeld dekat Augsburg pada 955, bangsa Magyar mengakhiri serbuan mereka ke Eropa dan beralih ke kehidupan menetap.", "f2c9d705"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0957-01-01:0":{"b": ["Olga pergi ke Konstantinopel dan dibaptis", "a418465b"], "d": ["Olga, janda Knyaz Kiev Igor yang wafat pada 945, mengunjungi Istanbul pada 957 dan di sana dibaptis menjadi Ortodoks (kemungkinan ia sudah pernah dibaptis sebelumnya di Kiev). Putranya Svyatoslav tetap pagan.", "874ba6e9"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0960-01-01:0":{"b": ["Raja Harald Blåtand dibaptis; pengkristenan Denmark secara de facto", "125e6961"], "d": ["Menurut EB1911, pengkristenan Denmark yang sebenarnya bertumpu pada pembaptisan Raja Harald Blåtand pada 960. Harald memperluas Danevirke, menaklukkan wilayah Jerman di selatan Eider, dan mendirikan koloni militer Julin (Jomsborg) di muara Oder.", "7d46c54b"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0966-01-01:0":{"b": ["Mieszko I menerima agama Kristen; awal negara Polandia", "f196c432"], "d": ["Mieszko I, penguasa bersejarah pertama wangsa Piast, menerima agama Kristen menurut ritus Latin pada 966 (menurut TDV mulai 967); keuskupan pertama didirikan paling lambat pada 968 di Posen (Poznan).", "46143293"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0969-01-01:0":{"b": ["Khalifah Muiz memanggil kembali keluarga Kalbi dan mengangkat Yaish sebagai gubernur; pemerintahan kembali ke tangan Kalbi", "60cf0e6b"], "d": ["Khalifah Muiz memanggil kembali keluarga Kalbi dan mengangkat Yaish sebagai gubernur; setelah kekacauan yang timbul, pemerintahan kembali ke tangan keluarga Kalbi.", "bc5be6e5"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0972-01-01:0":{"b": ["Svyatoslav dikalahkan dan tewas oleh pemimpin Pecheneg Kurya; perebutan takhta dimulai di antara putra-putranya", "5c81cd1a"], "d": ["Svyatoslav, yang telah mengalahkan bangsa Bulgar Volga dan Khazar, dikalahkan oleh Kurya, pemimpin Pecheneg sekutu Bizantium, dan gugur di medan perang pada 972; sesudah itu perebutan kekuasaan dimulai di antara putra-putranya.", "140047c5"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0980-01-01:0":{"b": ["Vladimir merebut Kiev dan membunuh Yaropolk; menjadi Pangeran Agung Kiev", "e3f74ebb"], "d": ["Vladimir, yang melarikan diri ke Novgorod dan mendatangkan bangsa Varangia dari Skandinavia, merebut Novgorod, Polotsk, dan kemudian Kiev pada 980; Yaropolk dibunuh. Selama 35 tahun Vladimir memperluas perbatasan Rus.", "af5c8d65"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0988-08-01:0":{"b": ["Penduduk Kiev dibaptis massal di Dnieper; pengkristenan Rus", "0e0d8243"], "d": ["Pada November 987 Vladimir dan orang-orang dekatnya dibaptis (di Kiev atau Chersonesos), lalu berhala-berhala dirobohkan; pembaptisan massal penduduk Kiev dilakukan pada 1 Agustus 988. Perpindahan agama ini, yang diberikan sebagai imbalan pernikahan dengan Anna, saudari Kaisar Bizantium Basileios II, mengikat Rus pada dunia Bizantium.", "e3274990"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0992-05-25:0":{"b": ["Mieszko I wafat; putranya Bolesław Chrobry memulihkan persatuan", "53190860"], "d": ["Mieszko, yang wafat pada 25 Mei 992, telah membagi-bagi wilayahnya di antara putra-putra dan kerabatnya; putra sulungnya, Bolesław sang Pemberani (Chrobry), dalam waktu singkat menyingkirkan para saingannya dan memulihkan persatuan negara.", "cfc21507"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0997-01-01:0":{"b": ["Setelah Géza, putranya István menjadi Pangeran Agung", "012ddcd9"], "d": ["Setelah wafatnya Géza (972-997), pangeran wangsa Árpád yang menanamkan agama Kristen, putranya István menggantikannya pada 997; ia meletakkan dasar negara Kristen.", "80fd9a0c"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:0997-01-01:1":{"b": ["Menurut saga, Olav Tryggvason mendirikan Nidaros (Trondheim)", "d51edb9c"], "d": ["Olav Tryggvason, raja Norwegia dari 995 hingga 1000, menurut saga mendirikan Nidaros (Trondheim) pada 997 dan mengkristenkan Islandia.", "e87e5759"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1000-01-01:0":{"b": ["István I dimahkotai dan mendirikan Kerajaan Kristen Hungaria (1000-1001)", "cff49a72"], "d": ["István menjadi raja pertama Hungaria yang dimahkotai pada akhir 1000 / awal 1001; organisasi gereja Hungaria (arsip dan keuskupan) ditata dengan dukungan kepausan.", "0e6edb9e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1000-01-01:1":{"b": ["Althing menerima agama Kristen sebagai agama resmi", "d7913660"], "d": ["Althing menerima agama Kristen sebagai agama resmi atas usul juru bicara hukum Þorgeir Ljósvetningagoði, 'satu hukum, satu agama' (tahun). SNL 'Islands historie' juga membenarkan: 'I 981 kom ... de første misjonærene til øya, og i 999/1000 fikk utsendinger fra Olav Tryggvason vedtatt kristendommen på Alltinget.'", "a4cc1ffd"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1004-01-01:0":{"b": ["Penyerbu Muslim menduduki Pisa untuk waktu singkat", "46c4642d"], "d": ["Pada 1004 armada Saracen merebut kota Pisa untuk waktu singkat; setelah itu Pisa menjadi kekuatan laut dengan meraih kemenangan di Reggio pada 1005 dan di Sardinia pada 1015-16.", "b38373ca"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1014-02-03:0":{"b": ["Raja Svend Tveskæg (Forkbeard) wafat", "6e366e8b"], "d": ["Svend Tveskæg, yang memberontak terhadap Harald Blåtand dan naik takhta (paling lambat 987), wafat pada 3 Februari 1014; ia telah menaklukkan Inggris pada 1013. Putranya Knud (Cnut) kemudian mendirikan Kekaisaran Laut Utara.", "35cb3298"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1015-07-15:0":{"b": ["Pangeran Agung Vladimir wafat di Vyshhorod", "cb196371"], "d": ["Vladimir wafat pada 15 Juli 1015 di Vyshhorod dekat Kiev, ketika sedang menyiapkan ekspedisi melawan putranya Yaroslav; Sviatopolk I sempat naik takhta Kiev, dan perang takhta dengan Yaroslav pun dimulai (Liubech 1015).", "7b4ae861"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1019-01-01:0":{"b": ["Yaroslav mengalahkan Sviatopolk di Sungai Alta dan merebut kembali takhta Kiev", "b8e609ea"], "d": ["Yaroslav, yang pada 1018 dikalahkan di Sungai Bug oleh Sviatopolk dan mertuanya Bolesław, telah melarikan diri dari Kiev; pada 1019 ia menghancurkan Sviatopolk di Sungai Alta dengan pasukan Novgorod dan kembali ke takhta Kiev.", "51da7963"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1019-01-01:1":{"b": ["Setelah Jafar, Ahmad al-Kalbi menjadi emir Sisilia", "6816ece9"], "d": ["Setelah Jafar, Ahmad al-Kalbi menjadi emir Sisilia; ketidakpuasan rakyat melemahkan kekuasaan Kalbi.", "26f733c4"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1025-01-01:0":{"b": ["Bolesław Chrobry dimahkotai sebagai raja di Gniezno", "945fc5c1"], "d": ["Bolesław sang Pemberani dimahkotai di Gniezno pada Juni 1025, kemungkinan dengan persetujuan kepausan, dan menjadi raja pertama Polandia; ia wafat pada tahun yang sama.", "2e0b7316"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1026-01-01:0":{"b": ["Perjanjian Horodok: Yaroslav dan Mstislav membagi Rus sepanjang Dnieper", "d88e1d56"], "d": ["Yaroslav, yang pada 1024 dikalahkan oleh Mstislav di Lystven, terpaksa menyerahkan tepi kiri Dnieper kecuali Pereyaslav kepada Mstislav; dengan perjanjian yang dicapai di Horodok pada 1026 kedua saudara itu beralih ke tatanan yang mapan. Pusat Mstislav adalah Chernigov.", "c371c785"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1027-01-01:0":{"b": ["Guaimario menjadi Pangeran Salerno; kepangeranan mencapai puncaknya", "bb536c3a"], "d": ["Guaimario (IV/V) menjadi Pangeran Salerno; pemerintahannya berlangsung hingga 1052 dan membawa kepangeranan itu ke puncaknya.", "416c3b7c"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1030-01-01:0":{"b": ["Adipati Napoli Sergius IV memberikan Aversa kepada Rainulf dari Norman; comte Norman pertama lahir di Italia Selatan", "b9d840ee"], "d": ["Adipati Sergius IV memberikan Aversa kepada Rainulf dari Norman sebagai imbalan dukungan melawan Pangeran Capua Pandulf; comte Norman pertama lahir di Italia Selatan.", "c5cc04b0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1030-01-01:1":{"b": ["Yaroslav sang Bijak menaklukkan wilayah antara Danau Peipus dan Baltik dan mendirikan Yuryev (Tartu)", "40165af3"], "d": ["Pada 1030 Yaroslav menaklukkan wilayah antara Danau Peipus dan Baltik, dan di sana mendirikan kota Yuryev, yang namanya berasal dari nama Kristennya Yuri (Georgi); kota itu adalah Tartu di Estonia sekarang.", "9dcb000d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1030-07-29:0":{"b": ["Pertempuran Stiklestad: Raja Olav II Haraldsson gugur di Trøndelag", "b774bc0b"], "d": ["Pada 29 Juli (kemungkinan besar 1030) di Stiklestad di Trøndelag (kini Verdal), Olav, yang kembali dari pengasingan dan ingin merebut kembali Norwegia, berhadapan dengan para tokoh dan petani setempat lalu tewas. Olav kemudian menjadi santo nasional Norwegia; dominasi Denmark berlangsung beberapa tahun.", "6e621a73"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1032-01-01:0":{"b": ["Keluarga Orseolo diasingkan; kecenderungan membentuk dinasti dipatahkan secara tegas", "6a137c97"], "d": ["Pada 1032 keluarga Orseolo diusir sepenuhnya dari Venesia dan doge Domenico Flabanico dipanggil ke takhta; ini adalah langkah kelembagaan pertama melawan jadinya jabatan doge sebuah dinasti.", "95963f43"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1035-11-12:0":{"b": ["Knud den Store wafat; Kekaisaran Laut Utara bubar", "3df57da6"], "d": ["Knud (Cnut), yang menyatukan Denmark, Inggris, dan Norwegia dalam satu takhta, wafat pada 12 November 1035; ia raja Denmark sejak 1018 dan raja Inggris sejak 1016. Norwegia menjadi miliknya pada 1028-1035; persatuan itu tidak bertahan lama setelah wafatnya.", "cb4bc5bc"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1036-01-01:0":{"b": ["Dengan wafatnya Mstislav, Yaroslav menjadi penguasa tunggal; bangsa Pecheneg dikalahkan telak", "34f5f3bb"], "d": ["Pada 1036, setelah wafatnya Mstislav, Yaroslav juga mencaplok wilayahnya (kecuali Polotsk) dan menjadi penguasa tunggal Kiev Rus; pada masa yang sama ia mengalahkan telak bangsa Pecheneg yang menyerang Kiev (1037) dan memulai pembangunan Katedral Santa Sophia.", "cd963cdb"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1038-01-01:0":{"b": ["Raja István I wafat; masa kekacauan dalam wangsa Árpád", "dd9fbb59"], "d": ["Setelah wafatnya István pada 1038, dimulailah empat puluh tahun yang kacau hingga 1077; Hungaria terseret ke dalam pertikaian kekaisaran-kepausan. Dalam wangsa Árpád, dua puluh tiga raja berganti hingga 1301.", "3e901e53"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1038-01-01:1":{"b": ["Pasukan Ziri membunuh Emir Kalbi Ahmad; saudaranya Hasan as-Samsam menggantikannya", "a8237799"], "d": ["Pasukan Ziri, yang dimintai tolong oleh rakyat, membunuh Ahmad; saudaranya Hasan as-Samsam didatangkan sebagai penggantinya (entri TDV Ibnü'l-Havvâs menyebut 1040).", "d17c0e2e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1042-01-01:0":{"b": ["Bangsa Norman memilih Melfi sebagai ibu kota; Guglielmo Demirkol dipilih sebagai comte Apulia", "c99feeb9"], "d": ["Tentara bayaran Norman yang berperang melawan Bizantium di Italia Selatan memilih Melfi sebagai ibu kota mereka pada 1042; pada September tahun yang sama Guglielmo (Demirkol), putra Tancred de Hauteville, dipilih sebagai comte. Inilah kelahiran de facto Kecomtean Norman Apulia.", "89954197"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1043-01-01:0":{"b": ["Ekspedisi Yaroslav ke Istanbul berakhir dengan bencana", "69fc1e8f"], "d": ["Pada 1043 pasukan Rus di bawah komando putranya Vladimir dan perwira Vyshata menyerang Konstantinopel; ekspedisi itu berakhir dengan kekalahan telak.", "93bcdced"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1052-06-03:0":{"b": ["Guaimario tewas dalam pembunuhan; Gisulf II merebut takhta dengan dukungan Norman", "5fd09721"], "d": ["Guaimario tewas dalam sebuah pembunuhan (tanggal 'kemungkinan 3 Juni'); Gisulfo II merebut kembali takhta dengan dukungan Norman dalam beberapa hari.", "3e19613d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1053-01-01:0":{"b": ["Pemerintahan Kalbi runtuh; pulau terpecah menjadi emirat-emirat lokal yang saling bersaing (445)", "efb37648"], "d": ["Hasan as-Samsam diusir dari Palermo, pemerintahan Kalbi runtuh, dan pulau itu terpecah menjadi emirat-emirat lokal yang saling bersaing (445).", "a8e0fb12"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1054-02-20:0":{"b": ["Yaroslav sang Bijak wafat di Kiev; proses perpecahan Rus dimulai", "031a5108"], "d": ["Yaroslav wafat di Kiev pada 20 Februari 1054. Setelah itu dimulailah perpecahan kenyazan yang berlangsung berabad-abad: menurut EB1911, antara 1054-1224 sedikitnya 64 kenyazan, meski singkat, pernah ada dan 293 knyaz mengajukan klaim suksesi.", "7a0f32c2"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1056-01-01:0":{"b": ["Kesepakatan uskup dan kaum bangsawan melahirkan otonomi komune Genoa", "d4a738e2"], "d": ["Pada 1056 kesepakatan antara uskup dan keluarga bangsawan berasal vicomte, serta pelepasan kewenangan yudisial oleh para markgraf Obertenghi, melahirkan otonomi kota Genoa; perusahaan dagang (compagne) berubah menjadi pemerintahan komune.", "f6828526"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1056-01-01:1":{"b": ["Ísleifur Gissurarson ditahbiskan sebagai uskup pertama Islandia; Skálholt menjadi pusat keuskupan", "7ee88c8e"], "d": ["Ísleifur Gissurarson ditahbiskan oleh Uskup Agung Bremen sebagai uskup pertama Islandia; Skálholt menjadi pusat keuskupan (tahun).", "22efb794"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1059-01-01:0":{"b": ["Guiscard mulai merebut wilayah dari kepangeranan Gisulf II", "98cc27be"], "d": ["Setelah Paus Nikolaus II memberikan gelar adipati Apulia dan Calabria kepada Robert Guiscard (1059), Guiscard mulai merebut kepangeranan Gisulf II sepotong demi sepotong.", "b688984f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1063-01-01:0":{"b": ["Armada Pisa menjarah pelabuhan Palermo", "a8156db8"], "d": ["Armada Pisa menjarah pelabuhan Palermo; dengan jarahan itu pembangunan Katedral Pisa dimulai.", "a29b8c6c"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1066-09-25:0":{"b": ["Harald Hardråde tewas di Stamford Bridge", "a9e2a898"], "d": ["Raja Norwegia Harald Hardråde tewas pada 25 September 1066 di Stamford Bridge (Yorkshire), Inggris; Harald menikahi Elisiv, putri Pangeran Agung Kiev Yaroslav, pada 1043/44.", "654f1496"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1068-01-01:0":{"b": ["Pertempuran Misilmeri: Bangsa Norman mengalahkan pasukan Muslim yang menghadang jalan ke Palermo", "362ca837"], "d": ["Pada 1068 di Misilmeri dekat Palermo, bangsa Norman meraih kemenangan penting dan menguasai jalan-jalan menuju Palermo.", "555852a2"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1068-01-01:1":{"b": ["Orang-orang Ayyub yang datang dengan armada Ziri membunuh Ibnu'l-Hawwas, emir terkemuka kaum Muslim pulau itu", "8367d1fb"], "d": ["Orang-orang Ayyub yang datang dengan armada Ziri membunuh Ibnu'l-Hawwas, emir terkemuka kaum Muslim pulau itu (460).", "6c81c4c0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1072-01-01:0":{"b": ["Palermo menyerah kepada Comte Roger dan Robert Guiscard; ibu kota Islam menjadi Norman", "f7be77c0"], "d": ["Setelah pengepungan darat dan laut selama lima bulan, Palermo menyerah pada 1072 dengan syarat-syarat yang lunak; Roger merebut kota itu atas nama kakaknya Robert Guiscard. Sejak tahun ini Roger memakai gelar 'comte Sisilia'.", "44fe7ca7"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1077-01-01:0":{"b": ["Perjalanan ke Canossa: Heinrich IV memohon ampun di hadapan Paus Gregorius VII di kastel Matilda", "c55345ff"], "d": ["Puncak Perselisihan Investitur antara Paus Gregorius VII dan Kaisar Heinrich IV terjadi pada 1077 di Kastel Canossa milik Matilda; sang kaisar dipermalukan di hadapan paus.", "0ceb34d7"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1082-01-01:0":{"b": ["Kaisar Bizantium Alexios Komnenos memberikan hak dagang luas kepada Venesia dengan Bulla Emas (chrysobull)", "dbb20bd5"], "d": ["Dengan chrysobull yang dikeluarkan pada Mei 1082 sebagai balasan atas bantuan laut melawan bangsa Norman, orang Venesia memperoleh hak berdagang bebas pajak di Kekaisaran Bizantium; menurut Treccani, hak istimewa ini diperluas dengan keikutsertaan dalam Perang Salib dan mencapai puncaknya pada Perang Salib Keempat.", "0b3ae24d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1085-07-17:0":{"b": ["Robert Guiscard wafat di Kefalonia; Roger Borsa menjadi adipati Apulia", "e1dbeef9"], "d": ["Robert Guiscard wafat di Kefalonia; Roger Borsa, yang ditunjuknya sebagai pewaris, menjadi adipati Apulia. Treccani juga membenarkan tanggal wafatnya: 'quando la morte lo colpiva il 17 luglio 1085' (Enciclopedia Italiana 'Roberto il Guiscardo').", "ab676a5f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1086-07-10:0":{"b": ["Knud IV (Santo Knud) dibunuh di Gereja Sankt Albani, Odense", "6654e332"], "d": ["Knud IV, raja Denmark sejak 1080, dibunuh pada 10 Juli 1086 di Gereja Sankt Albani di Odense ketika sedang menyiapkan ekspedisi baru ke Inggris; ia dinyatakan sebagai santo pada 1100.", "e1f2de9a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1096-01-01:0":{"b": ["Althing menerima persepuluhan gereja, pajak pertama Islandia (1096-97)", "eb2602c1"], "d": ["Atas upaya Uskup Gissur Ísleifsson, Althing menerima persepuluhan gereja, pajak sejati pertama Islandia (Althing 1096-97; tahun). SNL 'Islands historie': 'Under hans sønn Gissur ble tiende innført, og det ble også opprettet et bispesete på Hólar'.", "dd8908e8"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1097-01-01:0":{"b": ["Komune Milano didirikan (penyelesaian proses)", "b0acfa2b"], "d": ["Setelah gerakan pataria pada pertengahan abad ke-11 dan perjuangan reformasi gereja, proses pelembagaan Komune Milano dianggap selesai sekitar 1097.", "53d0a31a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1097-01-01:1":{"b": ["Kongres Liubech: para knyaz menerima prinsip mempertahankan tanah warisan ayah", "5d95e535"], "d": ["Kongres Liubech (1097), yang diselenggarakan atas prakarsa Volodymyr Monomakh, mengubah tatanan suksesi (sistem rota) secara mendasar; setiap knyaz akan mempertahankan wilayah turun-temurun ayahnya.", "7ec0e84a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1098-01-01:0":{"b": ["Bohemund memberikan hak dagang luas kepada orang Genoa yang membantu dalam pengepungan Antiokhia", "3c6b06d3"], "d": ["Bohemund dari Taranto memberikan hak dagang luas di kota itu kepada orang Genoa yang mendukung pengepungan Antiokhia selama Perang Salib Pertama; dengan demikian dimulailah kolonisasi Genoa di Mediterania Timur.", "f1cccd5f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1100-08-01:0":{"b": ["Perang Salib resmi pertama Komune Genoa berangkat", "4be1bc2c"], "d": ["Setelah usaha-usaha perang salib swasta (1097; ekspedisi Guglielmo Embriaco 1098-99), armada perang salib resmi pertama Komune Genoa berangkat pada 1 Agustus 1100; kolonialisme Genoa di Timur dimulai.", "2ac9e677"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1102-01-01:0":{"b": ["Kálmán menaklukkan Kroasia (1097-1102) dan Dalmatia (1102-1105)", "312e9720"], "d": ["Kálmán, yang menumpas pemberontakan Kroasia, menaklukkan Kroasia pada 1097-1102; pada 1102-1105 ia juga membawa kota-kota Dalmatia di bawah kekuasaan Hungaria (awal dominasi Hungaria di Zadar 1105 atau 1107). Kota-kota Dalmatia mempertahankan hak istimewa kotapraja mereka.", "faa4f775"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1111-01-01:0":{"b": ["Roger Borsa wafat, digantikan putranya William II", "f50e48f0"], "d": ["Roger Borsa wafat; putranya William II menggantikannya.", "824b3661"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1112-01-01:0":{"b": ["Ibu kota kecomtean dipindahkan ke Palermo", "091eb9c0"], "d": ["Adelasia, wali Roger yang masih kecil, pada 1112 memindahkan ibu kota Kecomtean Sisilia ke Palermo, yang berpenduduk Muslim padat; hal ini menegaskan orientasi Mediterania negara itu.", "60bcb773"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1113-01-01:0":{"b": ["Setelah pemberontakan Kiev, Volodymyr Monomakh naik takhta Kiev", "2fdd083a"], "d": ["Setelah wafatnya Sviatopolk II dan pemberontakan Kiev 1113, Monomakh, Knyaz Pereyaslav, menjadi pangeran agung Kiev; ia melakukan reformasi hukum dan ekonomi serta berusaha menciptakan persatuan melawan bangsa Kuman.", "05f60d47"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1113-01-01:1":{"b": ["Dengan restu paus, Pisa melancarkan perang salib ke Kepulauan Balearik (1113-1115)", "e925ee29"], "d": ["Dengan restu paus, Pisa melancarkan perang salib ke Kepulauan Balearik (1113-1115).", "a2f2966a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1115-01-01:0":{"b": ["Setelah wafatnya Comtesse Matilda, Firenze meraih otonomi komune", "a0b9a800"], "d": ["Setelah wafatnya Matilda di Canossa pada 1115, Firenze untuk pertama kalinya diakui otonomi kotanya; konsul pertama disebut pada 1138. Komune kemudian mengalahkan Fiesole (1125) dan para bangsawan kecomtean.", "4fb4d78b"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1115-01-01:1":{"b": ["Dengan wafatnya Matilda, markgraf kekaisaran mulai diangkat untuk Toskana", "36775155"], "d": ["Setelah wafatnya Comtesse Matilda dari Canossa pada 1115, para kaisar berusaha mengangkat serangkaian markgraf Jerman untuk Toskana; markgraf-markgraf ini lemah karena otonomi kota, dan setelah Friedrich I tempat mereka diambil alih oleh 'delegasi' dan 'wakil' kekaisaran.", "988cd50b"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1115-07-24:0":{"b": ["Comtesse Matilda wafat; berakhirnya Wangsa Canossa (warisannya menjadi sengketa antara kepausan dan kekaisaran)", "4d3a851d"], "d": ["Wangsa Canossa (Canossa/Matilda) berakhir (kepastian: {\"f\": \"yuzyil\", \"t\": \"gun\"}) Juga 'Matilde di Canossa' https://www.treccani.it/enciclopedia/matilde-di-canossa/ : Harta Matilda mencakup Brescia, Bergamo, Mantova, serta kecomtean Arezzo, Siena, dan Corneto.", "e54dd4f9"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1125-01-01:0":{"b": ["Orang Venesia meratakan Modon, sarang bajak laut", "788577af"], "d": ["Modon, yang pada Abad Pertengahan merupakan pangkalan laut kecil tetapi berbenteng kokoh, menjadi sarang bajak laut; orang Venesia meratakannya pada 1125. Kota itu tetap berupa reruntuhan hingga 1205, ketika bangsa Frank merebut Morea.", "a24897f1"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1125-05-19:0":{"b": ["Monomakh wafat di Kiev; penguasa terakhir Rus yang bersatu", "a4d61f0b"], "d": ["Volodymyr Monomakh wafat di Kiev pada 19 Mei 1125. Encyclopedia of Ukraine menyebutnya 'pangeran Rus terakhir yang memerintah negara bersatu'.", "cb8a41da"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1127-01-01:0":{"b": ["Roger II dinyatakan sebagai adipati oleh pasukan di Reggio", "e19f4cba"], "d": ["Roger, yang menuntut warisan setelah wafatnya Adipati Apulia William II, dielu-elukan oleh pasukannya sebagai adipati Apulia di Reggio saat kembali ke Sisilia pada akhir 1127; Paus Honorius II mengucilkannya.", "8f30bc01"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1127-01-01:1":{"b": ["Adipati William II wafat tanpa anak; garis Hauteville punah di Apulia", "43535228"], "d": ["Adipati William II wafat tanpa anak (Juni/Juli 1127); garis Hauteville punah di Apulia dan Roger II menuntut warisan.", "d5eca822"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1128-08-22:0":{"b": ["Di dekat Benevento, Paus Honorius II mengakui Roger II sebagai adipati Apulia, Calabria, dan Sisilia", "67e94015"], "d": ["Pada 22 Agustus 1128 di dekat Benevento, paus menginvestitur Roger sebagai adipati Apulia, Calabria, dan Sisilia; sebagai imbalannya, kendali kepausan atas Benevento dan kekebalan Kepangeranan Capua dijamin. Kadipaten Apulia menyatu dengan Kecomtean Sisilia.", "08889c27"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1130-12-25:0":{"b": ["Roger II dimahkotai sebagai raja Sisilia di Palermo", "edd9c9d4"], "d": ["Dalam skisma setelah wafatnya Paus Honorius II (13 Februari 1130), Roger memperoleh mahkota kerajaan dari Anacletus II dan diinvestitur pada 27 September 1130; ia dimahkotai sebagai raja di Palermo pada hari Natal. Kerajaan itu mencakup Pulau Sisilia dan Italia Selatan hingga Abruzzi.", "2fc371e4"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1134-01-01:0":{"b": ["Raja Sverker menyatukan bangsa Svea dan Göt di Swedia secara permanen (1134-1155)", "a6602794"], "d": ["Pada masa pemerintahan Raja Sverker (1134-1155), bangsa Swedia dan Göt bersatu dalam tatanan yang selama seratus tahun bergantian menghasilkan raja bersama; organisasi monarki terpusat menguat.", "21006781"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1135-01-01:0":{"b": ["Roger II mulai mengepung Napoli selama sekitar dua tahun (1135-1137)", "45bb0ec2"], "d": ["Ruggero II mulai mengepung Napoli selama sekitar dua tahun (1135-1137).", "d7d68b12"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1138-01-01:0":{"b": ["Wasiat Bolesław III: negara dibagi di antara putra-putranya, sistem senioritas dimulai", "d56e787c"], "d": ["Bolesław III, yang wafat pada 1138, membagi negara di antara putra-putranya dan memberlakukan sistem senioritas yang memberikan otoritas pusat kepada saudara tertua yang menyandang gelar 'adipati agung'; pengaturan ini menyebabkan masa perpecahan (fragmentasi) 1138-1320.", "8a7d818d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1139-07-25:0":{"b": ["Di Mignano, Paus Innocentius II mengakui kerajaan Roger II", "943c1dad"], "d": ["Setelah wafatnya Anacletus pada Januari 1138, Roger II mengakui Innocentius; pada 25 Juli 1139 di Mignano (dekat Montecassino) paus menginvestitur Roger sebagai raja Sisilia, Pangeran Capua, dan Adipati Apulia, serta mengesahkan sub-feodal yang diberikan kepada putra-putranya. Roger menyatakan dirinya vasal kepausan.", "087c0432"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1148-01-01:0":{"b": ["Bangsa Norman merebut Sfax (bersama Mahdia dan Gabes, 1148)", "e0a296e4"], "d": ["Pada 1148 armada Roger II merebut Mahdia, ibu kota Ziri, serta Gabes dan Sfax; penaklukan ini mendorong khalifah Muwahhidun Abdul Mukmin berekspedisi ke Maghrib Timur.", "a3c4ed88"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1150-01-01:0":{"b": ["Erik IX menata organisasi gereja; perang salib ke Finlandia memulai dominasi Swedia di seberang laut", "c67837dc"], "d": ["Raja Erik IX (1150-1160) mengorganisasi gereja Swedia menurut model Barat dan, dengan perang salib melawan bangsa Finlandia yang pagan, memulai kekuasaan Swedia di seberang laut. (Tahun ekspedisi tidak disebutkan dalam sumber.)", "be71462d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1152-01-01:0":{"b": ["Keuskupan Agung Nidaros didirikan; Greenland juga dimasukkan ke provinsi gereja Norwegia (1152/53)", "07106410"], "d": ["Dasar Keuskupan Agung Nidaros diletakkan selama kehadiran kardinal Inggris Nicolaus Breakspear di Trondheim pada 1152/53; pada 1153 keuskupan Greenland juga dimasukkan ke provinsi gereja Norwegia.", "ed706fc3"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1156-01-01:0":{"b": ["Novgorod memperoleh uskup agungnya sendiri", "7dddc3e3"], "d": ["Novgorod, yang merupakan pusat keuskupan dalam metropolitanat Kiev, memiliki uskup agung sendiri sejak 1156; uskup agung kelak menjadi ketua dewan boyar.", "29646afc"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1156-06-18:0":{"b": ["Perjanjian Benevento: Paus Hadrianus IV mengakui kerajaan William I", "caaa5258"], "d": ["Ketegangan antara Raja William I dan kepausan diselesaikan pada 18 Juni 1156 dengan perjanjian yang ditandatangani di Benevento setelah perundingan yang dipimpin Roland Bandinelli (kelak Alexander III) dan Maione; perjanjian itu mengulang hubungan masa Roger II dan menambahkan konsesi baru.", "7a8656eb"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1157-01-01:0":{"b": ["Valdemar I mengalahkan Svend di Grathe Hede dan menjadi raja Denmark", "e8aab76b"], "d": ["Setelah perang takhta yang panjang, Valdemar I, putra Knud Lavard, mengalahkan Svend di Grathe Hede pada 1157 dan menjadi raja tunggal; zaman Valdemar di Denmark (bersama Absalon) dimulai.", "af67ecff"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1157-01-01:1":{"b": ["Andrey Bogolyubskiy menyatukan Rostov-Suzdal; Vladimir menjadi ibu kota", "08e870ec"], "d": ["Andrey, yang meninggalkan Vyshhorod dan menetap di Vladimir pada 1155, menjadi knyaz Rostov dan Suzdal pada 1157 dengan wafatnya ayahnya Yuri Dolgorukiy; ia menyatukan Rus timur laut di bawah satu tangan.", "a1132354"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1162-01-01:0":{"b": ["Perjanjian dengan Barbarossa: Genoa diakui memiliki feodum Riviera", "3b2c6e0a"], "d": ["Perjanjian dengan Kaisar Friedrich Barbarossa pada 1162 menjamin infeodasi Riviera kepada Genoa; tembok baru dibangun pada tahun yang sama. Hingga tanggal ini politik Genoa bertumpu pada persekutuan dengan Sisilia Norman.", "aeb618ab"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1162-01-01:1":{"b": ["Pengepungan Barbarossa berakhir dengan penyerahan Milano dan penghancuran temboknya", "c4e917bb"], "d": ["Milano, yang dilarang dengan maklumat kekaisaran pada 1155 dan dikepung serta menyerah pada 1158, setelah pengepungan panjang menyerah pada 1162 di hadapan musuh-musuhnya (Lodi, Como, Pavia, Cremona, Novara, dan pasukan kekaisaran); tembok dihancurkan dan penduduk terpaksa tinggal di luar kota selama empat tahun.", "9851b3b0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1162-01-01:2":{"b": ["Barbarossa mengakui otonomi dan hak istimewa komune Pisa", "86dd940d"], "d": ["Friedrich Barbarossa mengakui otonomi dan wilayah/hak istimewa luas komune Pisa.", "c350ab79"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1164-01-01:0":{"b": ["Keuskupan/keuskupan agung Kristen pertama didirikan di Uppsala", "7ade3836"], "d": ["Dengan dihancurkannya kuil Uppsala dan didirikannya keuskupan Kristen pertama di sana (1164), agama Kristen menang di Swedia; setelah keuskupan agung Denmark di Lund, keuskupan agung Uppsala juga bertanggal 1164.", "58037f18"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1166-05-07:0":{"b": ["Raja William I wafat di Palermo", "88d80bbb"], "d": ["William I yang berjuluk buruk wafat di Palermo pada sore hari 7 Mei 1166 pada usia 46 tahun; putranya William II yang berusia 12 tahun naik takhta di bawah perwalian ibunya Margherita. Penaklukan Roger di Afrika hilang pada masa ini.", "871f1e28"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1167-04-07:0":{"b": ["Sumpah Pontida: Liga Lombard (Lega Lombarda) didirikan", "09f9dc94"], "d": ["Pada 7 April 1167 di biara Pontida, komune-komune Lombard bersumpah bersatu melawan Barbarossa; kota-kota seperti Cremona, Bergamo, Brescia, Mantova, dan Milano bergabung.", "4fab9bd9"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1169-03-08:0":{"b": ["Para knyaz sekutu Andrey Bogolyubskiy menyerbu dan menjarah Kiev", "ff66c1e9"], "d": ["Para knyaz sekutu Andrey Bogolyubskiy menyerbu dan menjarah Kiev; bobot kota itu sebagai ibu kota berkurang. Encyclopedia of Ukraine juga membenarkan peristiwa yang sama: 'In 1169 he sacked Kyiv'. Bobot Kiev sebagai ibu kota praktis bergeser ke Vladimir.", "9ffe3724"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1171-01-01:0":{"b": ["Dewan Agung (Maggior Consiglio) didirikan; pemilihan doge beralih ke aristokrasi", "9f313418"], "d": ["Setelah bencana Bizantium pada 1171, dilakukan reformasi konstitusi; Dewan Agung didirikan. Sejak 1172, ketika Ziani terpilih, doge baru hanya dihadapkan kepada rakyat untuk disetujui.", "0fadae7a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1174-01-01:0":{"b": ["Andrey Bogolyubskiy dibunuh para boyar di Bogolyubovo", "b2460640"], "d": ["Andrey Bogolyubskiy dibunuh para boyarnya di Bogolyubovo; perebutan takhta 1174-1177 dimulai (tanggal pastinya bertentangan dalam sumber: 28/29 Juni).", "bba50723"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1175-01-01:0":{"b": ["Perdamaian Pavia membagi Sardinia antara Pisa dan Genoa", "5583ade4"], "d": ["Perdamaian Pavia membagi Sardinia antara Pisa dan Genoa.", "ca5040ae"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1177-07-24:0":{"b": ["Perdamaian Venesia: Kaisar Barbarossa dan Paus Alexander III berdamai di San Marco", "db7f6f5e"], "d": ["Perundingan antara Liga Lombard dan Barbarossa dilakukan di Venesia; pada hari Minggu 24 Juli 1177, kaisar dan paus berdamai dengan upacara di Basilika San Marco. Perdamaian itu dianggap kemenangan diplomasi Venesia.", "c2e5c88f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1183-06-25:0":{"b": ["Perdamaian Konstanz: Barbarossa mengakui otonomi komune Lombard", "bfc8b988"], "d": ["Dengan perdamaian yang ditandatangani di Konstanz pada 1183, kaisar mengakui komune-komune dan Liga; Milano memperoleh hak memilih konsulnya sendiri (tanpa melibatkan uskup agung), terikat langsung pada kekaisaran.", "ca3cbc91"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1189-01-01:0":{"b": ["Raja William II wafat tanpa anak; krisis suksesi dimulai", "2fddc4e1"], "d": ["William II, yang tidak memiliki anak, wafat pada 1189 pada usia baru 36 tahun; sebagai penggantinya telah diperkirakan putri bibinya, Constance (istri Henry VI dari Hohenstaufen), tetapi para bangsawan memilih Tancred, Comte Lecce.", "97145a32"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1190-01-18:0":{"b": ["Tancred, Comte Lecce, dimahkotai sebagai raja Sisilia di Palermo", "4db4c2ff"], "d": ["Tancred terpilih sebagai raja pada 8 Desember 1189 dan dimahkotai oleh Uskup Agung Palermo Gualtiero pada 18 Januari 1190; dengan demikian perjuangan melawan Henry VI dari Hohenstaufen dimulai.", "d5d6986e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1192-06-21:0":{"b": ["Enrico Dandolo terpilih sebagai doge pada usia 85 tahun", "8aeb9a04"], "d": ["Setelah wafatnya Doge Orio Mastropiero pada 14 Juni 1192, Enrico Dandolo yang berusia 85 tahun dan buta terpilih sebagai doge pada 21 Juni 1192; dialah tokoh yang kelak mengarahkan Perang Salib Keempat.", "080e251e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1194-02-20:0":{"b": ["Raja Tancred wafat di Palermo; akhir de facto wangsa Norman", "5f088c55"], "d": ["Tancred wafat pada 20 Februari 1194; ia telah kehilangan putra sulungnya Roger III beberapa bulan sebelumnya (24 Desember 1193). Naiknya putra bungsunya William III ke takhta tidak dapat mencegah penaklukan oleh Henry VI.", "f0fd8705"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1194-12-25:0":{"b": ["Henry VI dimahkotai sebagai raja Sisilia di Palermo; kerajaan beralih ke Hohenstaufen", "421ad808"], "d": ["Henry VI memasuki Palermo pada 20 November 1194 dan dimahkotai sebagai raja pada hari Natal; keesokan harinya putranya Frederick lahir di Jesi. Kerajaan Sisilia beralih dari wangsa Norman ke wangsa Hohenstaufen.", "8da541e5"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1197-01-01:0":{"b": ["Kota-kota Toskana mendirikan Liga San Ginesio; Firenze memimpin", "bfb52345"], "d": ["Dalam liga kota-kota Toskana yang anti-kaisar dan pro-paus, yang didirikan di San Ginesio pada 1197 setelah wafatnya Henry VI, Firenze tampil menonjol; arah kebijakan luar negeri Firenze sejak itu adalah ini.", "7759a0cd"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1198-01-01:0":{"b": ["Přemysl Ottokar I dimahkotai sebagai raja Bohemia (penguasa 1197, mahkota 1198)", "49201be5"], "d": ["Přemysl Ottokar I, yang menjadi penguasa Bohemia yang tak terbantahkan pada 1197, dimahkotai sebagai raja pada 1198; dengan Bulla Emas Sisilia 1212, gelar raja menjadi turun-temurun dan hubungan dengan kekaisaran diatur.", "0cf21980"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1198-05-17:0":{"b": ["Frederick kecil dimahkotai sebagai raja Sisilia di Palermo (kelak Friedrich II)", "79b0af82"], "d": ["Setelah wafatnya Henry VI pada 1197, putranya Frederick yang berusia tiga tahun dimahkotai di Palermo pada 17 Mei 1198; dengan wafatnya ibunya Constance, pewaris Norman itu berada di bawah perwalian Paus Innocentius III.", "09ece983"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1199-01-01:0":{"b": ["Roman Mstislavich menyatukan Galisia dan Volhynia", "edf59754"], "d": ["Roman Mstislavich, Knyaz Volhynia yang merebut Halych dengan wafatnya knyaz Rostislavich terakhir Halych, Volodymyr Yaroslavich, pada 1199, menyatukan Galisia dan Volhynia dan mendirikan Kenyazan Galisia-Volhynia; wangsa Romanovich memerintah hingga 1340.", "6e7123e0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1201-01-01:0":{"b": ["Uskup Livonia, Albert, mendirikan Riga / memindahkan pusat keuskupan ke Riga", "8f99d26f"], "d": ["Setelah bangsa Jerman mendarat di muara Dvina pada 1158 dan misi uskup agung Bremen pada 1186, uskup Livonia menempatkan pusatnya di Riga pada 1201; tak lama kemudian Ordo Saudara Pedang (1202/1204) didirikan.", "6134e663"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1202-01-01:0":{"b": ["Ordo Saudara Pedang (Ordo Livonia) diakui oleh kepausan", "f53f7643"], "d": ["Paus Innocentius III mengakui Ordo Saudara Pedang pada 1202 atau 1204; pusat ordo adalah Wenden (Cēsis). Ordo itu membuka masa perang tanpa henti melawan bangsa Rus dan Lituania.", "9a812c20"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1204-01-01:0":{"b": ["Pembagian Romania (Partitio Romaniae): bangsa Latin membagi wilayah Bizantium", "8f498e2a"], "d": ["Setelah Perang Salib Keempat merebut Istanbul (1204), orang Venesia dan tentara salib menyepakati Partitio Romaniae untuk membagi jarahan dan wilayah Bizantium. Treccani DBI menekankan bahwa pengaturan ini mengatur wilayah milik doge dan orang-orangnya, bukan milik Komune Venesia, dan bahwa komune secara sistematis dikecualikan dari rencana pembagian.", "75d36572"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1205-01-01:0":{"b": ["Ragusa (Dubrovnik) diserahkan kepada Venesia setelah pemerintahan singkat comte lokal Damiano Giuda", "1533457b"], "d": ["Ragusa, yang berpindah-pindah antara Kerajaan Sisilia (1187) dan Bizantium (1192), pada 1205 setelah dominasi singkat comte lokal Damiano Giuda menyerahkan dirinya kepada Venesia; pemerintahan Venesia berlangsung sekitar 150 tahun.", "964f2c7a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1205-01-01:1":{"b": ["Doge Enrico Dandolo wafat selama penarikan mundur yang tertata", "e5a66067"], "d": ["Enrico Dandolo, pemimpin Venesia dalam Perang Salib Keempat, wafat selama penarikan mundur pada Mei-Juni 1205 dan dimakamkan di Hagia Sophia.", "c1c02f08"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1209-01-01:0":{"b": ["Orang Venesia (kembali) merebut Modon, menempatinya, dan memperkuat pertahanannya", "4e7f4797"], "d": ["Orang Venesia merebut kembali Modon pada 1209; kota ini beserta Koron (Coron) di dekatnya menjadi pos pengawasan dan stasiun pasokan di tengah jalur Venesia-Levant.", "7098530d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1217-06-01:0":{"b": ["Haakon IV terpilih sebagai raja Norwegia pada usia 13 tahun", "8303b789"], "d": ["Partai Birkebeiner pada 1217 menaikkan putra dan senama Haakon III ke takhta; Haakon IV memerintah hingga 1263 dan membawa zaman keemasan Norwegia.", "727e8c33"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1219-01-01:0":{"b": ["Valdemar II berekspedisi salib ke Estonia dan mendirikan Tallinn (Lyndanisse)", "e4c18608"], "d": ["Valdemar II pada 1219 menduduki Estonia Utara dalam kerangka perang salib ke Baltik Timur dan membangun benteng di Tallinn; kota itu menjadi pusat keuskupan. Menurut kisah tradisional, Dannebrog turun dari langit dalam perang ini (15 Juni 1219, Lyndanisse).", "8df3b0b9"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1222-01-01:0":{"b": ["Bulla Emas (Aranybulla): Endre II mengakui hak bangsawan untuk menentang tindakan melanggar hukum raja", "990bcd41"], "d": ["Pada 1222 Raja Endre II mengeluarkan maklumat bermeterai emas (Aranybulla) yang mengakui hak bangsawan (nobiles) untuk melawan perilaku raja yang bertentangan dengan hukum; ini tonggak menguatnya oligarki feodal.", "07b4c047"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1224-01-01:0":{"b": ["Friedrich II mendirikan universitas (studium) di Napoli untuk rakyatnya", "61741d0f"], "d": ["Friedrich II mendirikan studium generale di Napoli yang mengajarkan semua ilmu agar rakyatnya tidak perlu pergi belajar ke luar kerajaan; dimaksudkan sebagai alternatif bagi universitas-universitas Guelf di utara (Bologna).", "0efbf23a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1226-01-01:0":{"b": ["Liga Lombard Kedua diperbarui dengan sumpah di Mosio melawan Friedrich II", "beabd16d"], "d": ["Ketika Friedrich II menuntut sumpah setia dari komune-komune Lombard, komune-komune itu memperbarui Liga pada 1226; Milano, Bologna, Brescia, Bergamo, Torino, Vicenza, Padova, Treviso, dan kemudian Piacenza, Verona, Faenza, dan lain-lain bergabung. Kaisar membatalkan hak istimewa Konstanz.", "fba47ebe"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1228-01-01:0":{"b": ["Adipati Masovia Konrad mengundang Ordo Teutonik ke perbatasan Prusia; menghibahkan tanah Kulm", "d9a2fb44"], "d": ["Konrad, yang tidak mampu menghadapi serbuan bangsa Prusia, mengundang Ordo Teutonik untuk membantu dan menyerahkan Kulm serta beberapa kota perbatasan beserta tanah yang akan ditaklukkan (1228); seluruh tanah Kulm diserahkan kepada ordo pada 1230. Penaklukan Prusia dimulai pada 1229 (benteng di Thorn).", "3451ab9f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1231-01-01:0":{"b": ["Konstitusi Melfi (Liber Augustalis) diundangkan", "66a65f82"], "d": ["Friedrich II pada 1231 mengumumkan himpunan hukum baru, Liber Augustalis, dari Melfi; administrasi kerajaan ditata ulang dari awal dengan naskah ini.", "e39c618e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1235-04-19:0":{"b": ["Amedeo IV memberikan sebagian besar Piemonte kepada saudaranya Tommaso sebagai apanase", "fe0c2b58"], "d": ["Amedeo IV, setelah perselisihan dengan saudara-saudaranya, pada 19 April 1235 menginvestitur saudaranya Tommaso (Tommaso II, Comte Flandre) sebagai pemilik seluruh Piemonte dari Avigliana ke bawah; inilah dasar cabang Piemonte wangsa Savoia.", "23c46f6d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1236-01-01:0":{"b": ["Mindaugas mengalahkan para ksatria Teutonik (1236)", "5199f385"], "d": ["Tekanan para ksatria Jerman mempercepat terbentuknya negara Lituania; Treccani menghubungkan kemenangan pada 1236 dengan Mindaugas, yang kemudian memeluk agama Kristen dan menjadi raja (1253).", "3c0a22cd"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1237-01-01:0":{"b": ["Di Cortenuova, Friedrich II mengalahkan pasukan Lombard dan merebut carroccio Milano", "940476af"], "d": ["Friedrich II, yang menduduki Vicenza, Treviso, dan Mantova, pada 1237 di Cortenuova menghancurkan sepenuhnya pasukan Liga dan merebut carroccio Milano.", "240098b2"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1237-01-01:1":{"b": ["Ordo Saudara Pedang bergabung dengan Ordo Teutonik; Livonia menjadi provinsi ordo", "20ac369b"], "d": ["Pada 1237 Ordo Saudara Pedang disatukan dengan Ordo Teutonik; Livonia menjadi provinsi yang memiliki mastternya sendiri dan terikat pada master agung. Dua tahun sebelumnya Ksatria Dobrzyń juga telah bergabung dengan ordo.", "e9e624d8"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1239-01-01:0":{"b": ["Invasi Mongol tidak sampai ke Novgorod, tetapi kota itu mengakui kekuasaan Gerombolan Emas dan membayar upeti", "ce817f73"], "d": ["Invasi Tatar 1239-40 tidak sampai ke Novgorod; namun kota itu terpaksa mengakui kekuasaan Gerombolan Emas dan membayar upeti kepada khan. Kemerdekaan relatif ini memungkinkan kota itu berkembang melalui perdagangan Hansa.", "f6bdd744"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1241-01-01:0":{"b": ["Armada Genoa kalah dalam pertempuran laut di lepas Pulau Giglio", "4d937092"], "d": ["Genoa, yang bersekutu dengan paus dan Venesia pada masa Friedrich II, kalah dalam pertempuran laut di lepas Pulau Giglio pada 1241; namun kota itu cepat pulih dan pada 1245 menegakkan kehendaknya di Konsili Lyon (yang diselenggarakan oleh Paus Innocentius IV dari Genoa).", "adcb4066"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1241-01-01:1":{"b": ["Bangsa Mongol menghancurkan Halych; Danylo memindahkan ibu kota ke Kholm", "429473c7"], "d": ["Bangsa Mongol menghancurkan Halych; Danilo memindahkan ibu kota ke Kholm (hari tidak diketahui, tahun yang pokok). Encyclopedia of Ukraine ('Galicia-Volhynia'): 'After the Mongols razed Halych in 1241, Kholm became the new capital.'", "d436f857"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1241-03-28:0":{"b": ["Valdemar II Sejr wafat", "b2f435e3"], "d": ["Valdemar II (Sejr), yang memperluas Denmark di Baltik hingga Estonia, wafat pada 28 Maret 1241; dengan wafatnya, masa perpecahan dimulai di negeri itu.", "516198f8"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1241-04-09:0":{"b": ["Pertempuran Legnica: Bangsa Mongol mengalahkan pasukan Adipati Silesia Henryk II", "5ba75b97"], "d": ["Pada 9 April 1241 di Legnica (Liegnitz), bangsa Mongol mengalahkan pasukan gabungan para pangeran Silesia, membakar kota-kota Silesia, dan bergerak ke Hungaria. Serbuan Mongol dari timur negeri itu membawa negara Polandia ke ambang perpecahan.", "360c53d6"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1248-01-01:0":{"b": ["Jarl Birger mulai memerintah Swedia secara de facto (1248-1266)", "b7d44ef8"], "d": ["Jarl Birger, yang dianggap negarawan terbesar Swedia abad pertengahan, memerintah negeri itu secara de facto dari 1248 hingga 1266 dan memperkuat otoritas kerajaan; Magnus Ladulås (1275-1290) melanjutkannya.", "7f65018f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1250-12-13:0":{"b": ["Kaisar Friedrich II wafat di Kastel Fiorentino", "32065dff"], "d": ["Friedrich II wafat karena demam usus pada 13 Desember 1250 di Kastel Fiorentino di Apulia (dekat Foggia); takhta Sisilia diserahkan kepada putranya Conrad IV, perwalian kepada Manfred.", "153ab3c0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1253-01-01:0":{"b": ["Danylo menerima mahkota dari paus dan menjadi Raja Rus", "604b4ddb"], "d": ["Danylo, yang mencari dukungan Barat melawan bangsa Mongol, menerima supremasi gerejawi Paus Innocentius IV dan menerima mahkota dari paus pada 1253; namun bantuan yang diharapkannya tidak datang.", "22e466fa"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1253-01-01:1":{"b": ["Mindaugas menerima agama Kristen dan dimahkotai sebagai raja Lituania", "424666af"], "d": ["Mindaugas memeluk Katolik pada 1253 dan dimahkotai sebagai raja, menyatakan Lituania sebagai kerajaan; para pengikutnya kembali ke paganisme.", "fc42f619"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1255-01-01:0":{"b": ["Benteng Ordo Teutonik didirikan untuk Raja Ottokar II dari Bohemia: Königsberg", "4b6bb21c"], "d": ["Kota yang tumbuh di sekitar benteng yang dibangun untuk Ordo Teutonik selama perang salib Raja Ottokar II di Prusia (1255) diberi nama Königsberg untuk menghormatinya. Kota itu dihancurkan dalam pemberontakan bangsa Prusia pada 1263 dan dibangun kembali pada 1286.", "7bc46742"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1257-01-01:0":{"b": ["Guglielmo Boccanegra mendirikan Kapten Rakyat", "b7753984"], "d": ["Setelah wafatnya Friedrich II pada 1250, menghadapi keluarga bangsawan lama dan baru (Fieschi, Grimaldi, Doria, Spinola), kaum borjuasi pada 1257 di bawah pimpinan Guglielmo Boccanegra mendirikan jabatan 'Kapten Rakyat' (capitano del Popolo); upaya kediktatoran Boccanegra ditumpas pada 1262.", "2eae2a56"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1258-08-11:0":{"b": ["Manfred dimahkotai sebagai raja Sisilia di Palermo", "95db5116"], "d": ["Manfred, yang menyebarkan kabar bahwa keponakannya Conradin telah wafat, merebut kembali kerajaan dari utusan kepausan dengan dukungan kaum Muslim Lucera dan dimahkotai sebagai raja di Palermo pada 1258.", "1047b259"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1259-01-01:0":{"b": ["Despot Epirus Michael II menyerahkan Korfu kepada Manfred", "19f2de3c"], "d": ["Pada 1259 Despot Epirus Mikhail II Angelos Komnenos menyerahkan Korfu kepada Raja Sisilia Manfred; pada 1267 pulau itu berpindah bersama Kerajaan Sisilia kepada Charles dari Anjou dan menjadi pangkalan laut bagi pengaruh Anjou di Balkan.", "1fe50b1f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1260-01-01:0":{"b": ["Pertempuran Montaperti: Sekutu Ghibellin Manfred mengalahkan kaum Guelf Toskana; Firenze kembali menjadi Ghibellin", "7ee3d67e"], "d": ["Kemenangan Montaperti pada 1260 menjadi puncak keberuntungan Manfred; Firenze kembali berada di bawah pemerintahan Ghibellin. Kekalahan Manfred di Benevento (1266) dan Tagliacozzo (1268) membawa kembalinya kaum Guelf.", "a3001f03"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1261-01-01:0":{"b": ["Perjanjian Nymphaeum: Genoa memperoleh hak dagang dari Bizantium ke Laut Hitam dan Mediterania Timur", "194b1f15"], "d": ["Dengan Perjanjian Nymphaeum yang ditandatangani dengan Kaisar Bizantium Mikhail VIII pada 1261, Genoa memperoleh hak istimewa luas di Laut Hitam dan Mediterania Timur; dasar koloni Pera-Galata dan kolonisasi Krimea (Kaffa) adalah perjanjian ini.", "6deda3b0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:0":{"b": ["Bonifacio wafat tanpa anak; pamannya Pietro II menjadi Comte Savoia", "38fe8bbd"], "d": ["Ketika Bonifacio, putra Amedeo IV yang masih kecil, wafat tanpa anak pada 1263, bertentangan dengan wasiat ayahnya, saudaranya Pietro II ('Charlemagne Kecil') menjadi comte menggantikan Tommaso III, putra Tommaso II.", "c18af671"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:1":{"b": ["Genoa kalah dari Venesia di Settepozzi; gencatan senjata Cremona ditandatangani", "060e901b"], "d": ["Perang Genoa-Venesia yang berlanjut setelah Nymphaeum diakhiri pada 1263 dengan kekalahan Genoa di Settepozzi dan gencatan senjata Cremona.", "83eacbcb"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:2":{"b": ["Bangsa Prusia memberontak dan menghancurkan inti pertama Königsberg", "9b09b809"], "d": ["Bangsa Prusia, yang memberontak melawan para kolonis Kristen pada 1263, menghancurkan inti pertama Königsberg; kota itu didirikan kembali di tempatnya sekarang (status kota pada 1286).", "63cc141a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-12-16:0":{"b": ["Haakon IV wafat di Orkney setelah Pertempuran Largs", "7df398fd"], "d": ["Haakon IV, yang berekspedisi ke Hebrides pada 1263 untuk memperkuat klaim Norwegia di Skotlandia, wafat di Orkney setelah Pertempuran Largs; pemerintahannya yang berlangsung sejak 1217 pun berakhir. Putranya Magnus Lagabøte mengakhiri perang dengan Skotlandia.", "a7f678c4"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1266-02-26:0":{"b": ["Pertempuran Benevento: Charles dari Anjou mengalahkan dan membunuh Manfred; kerajaan beralih ke Anjou", "40101cec"], "d": ["Pada 26 Februari 1266 di Benevento, Comte Anjou Charles menghancurkan pasukan Manfred; Manfred tewas di medan perang. Kerajaan Sisilia beralih dari wangsa Hohenstaufen ke wangsa Anjou.", "35ac3334"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1268-01-01:0":{"b": ["Pietro II wafat; saudaranya Filippo I menjadi Comte Savoia", "26cea9a1"], "d": ["Ketika Pietro II wafat pada 1268 tanpa anak laki-laki, hak Tommaso III kembali diabaikan; saudaranya Filippo I menjadi Comte Savoia. Dengan wafatnya Filippo (1285), kecomtean beralih kepada Amedeo V.", "74420d2e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1272-01-01:0":{"b": ["Lev Danyloviç memindahkan ibu kota ke Lviv", "1c030990"], "d": ["Lev Danyloviç memindahkan ibu kota ke Lviv.", "d6c8561a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1278-08-26:0":{"b": ["Pertempuran Marchfeld (Dürnkrut): Ottokar II dikalahkan dan tewas oleh Rudolph von Habsburg", "a3d38659"], "d": ["Dengan terpilihnya Rudolph von Habsburg sebagai Raja Romawi (1273), fief kekaisaran yang dipegang Ottokar diminta kembali, dan Ottokar melepaskan seluruh wilayahnya selain Bohemia dan Moravia. Ottokar, yang menyerang kadipaten Austria pada 1278, kalah dan tewas dalam pertempuran Dürnkrut di Marchfeld.", "683f6e78"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1280-05-09:0":{"b": ["Magnus Lagabøte wafat di Bergen", "1f4309b2"], "d": ["Magnus Lagabøte ('Pembaru Hukum'), putra Haakon IV, wafat di Bergen pada 9 Mei 1280; ia dimakamkan di gereja Olavskirke milik para Fransiskan.", "7c2cd8c3"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1328-08-16:0":{"b": ["Di Mantova, Luigi Gonzaga memberontak melawan signoria Bonacolsi dan merebut kekuasaan; zaman Gonzaga dimulai", "1bd79932"], "d": ["Pada 16 Agustus 1328 Luigi Gonzaga memberontak melawan signoria Bonacolsi yang memerintah Mantova dan merebut pemerintahan kota. Negara kota yang sama berlanjut dengan wangsa baru; keluarga Gonzaga memerintah Mantova hingga 1708.", "1c4bea74"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1052-01-01:0":{"b": ["Warga Amalfi mengusir Adipati Mansone dan berusaha lepas dari perwalian Salerno.", "ddfbbc83"], "d": ["Warga Amalfi mengusir Adipati Mansone dan berusaha lepas dari perwalian Salerno.", "ddfbbc83"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1076-01-01:0":{"b": ["Sinode Worms: Henry IV menyatakan Gregorius VII digulingkan; Gregorius mengucilkannya", "36e0ddb4"], "d": ["Sinode para uskup Jerman yang bersidang di Worms pada Januari 1076 menyatakan Gregorius digulingkan; Henry menulis kepada sang paus 'bukan paus, melainkan biarawan palsu'. Henry segera dikucilkan; pengikutnya berkurang dan bangsa Saxon mengangkat senjata.", "a40f48cd"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1088-01-01:0":{"b": ["Setelah wafatnya Guiscardo, Amalfi memberontak dan memproklamasikan Gisulfo sebagai adipati; pemerintahan Gisulf hanya berlangsung setahun.", "8f9b063e"], "d": ["Setelah wafatnya Guiscardo, Amalfi memberontak dan memproklamasikan Gisulfo sebagai adipati; pemerintahan Gisulf hanya berlangsung setahun.", "8f9b063e"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1096-01-01:0":{"b": ["Dengan pemberontakan baru, Marino Sebaste menjadi adipati.", "bd923d74"], "d": ["Dengan pemberontakan baru, Marino Sebaste menjadi adipati.", "bd923d74"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1122-01-01:0":{"b": ["Konkordat Worms: perselisihan investitur berakhir", "4b2cf229"], "d": ["Konkordat Worms 1122 mengakhiri perselisihan investitur yang berlangsung sejak Gregorius VII.", "5a532208"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1135-01-01:0":{"b": ["Armada Pisa menjarah Amalfi", "357149dc"], "d": ["Dalam kampanye 1135 (dan 1136-37), bangsa Pisa, yang datang membantu Pangeran Capua Robert di Napoli melawan Raja Sisilia Roger II, menghancurkan Amalfi dan menjarah Pulau İskele (Ischia).", "e362cfdf"]},
"OLAYLAR_ORTADOGU_0919:1801-01-01:0":{"b": ["Suku-suku sekitar Tâif masuk ke pengaruh Wahhabi — Türabe dan Hurma memisahkan diri dari Kesyarifan Mekah", "d3b644be"], "d": ["Suku-suku sekitar Tâif yang terikat pada Syarif Mekah Gālib masuk ke pengaruh Wahhabi pada 1801; emir Dir'iyah menyerahkan mereka ke pemerintahan syekh Badui Osman el-Mudâyifî, ipar sekaligus musuh sang Syarif. Oasis Türabe dan Hurma di timur juga beralih ke pihak Saudi pada rangkaian ini. Ini adalah pendahulu direbutnya Tâif dan kemudian Mekah oleh Wahhabi pada Februari 1803.", "4fe448d3"]},
"OLAYLAR_ORTADOGU_0919:1816-01-01:0":{"b": ["Garnisun Mesir mundur dari Türabe, Bîşe, dan Rânye di Hijaz selatan", "72b87aa1"], "d": ["Pada bulan-bulan setelah Tosun Paşa berdamai dengan Wahhabi dan kembali ke Kairo pada November 1815, timbul kekacauan di Hijaz selatan; garnisun Kavalalı Mehmed Ali Paşa terpaksa mundur dari Bîşe, Rânye, dan Türabe. Berangkatnya İbrâhim Paşa dari Kairo pada Agustus 1816 untuk ekspedisi baru menyusul mundurnya ini. Siapa yang memerintah Türabe hingga jatuhnya Dir'iyah (1818) tidak tertulis dalam sumber.", "90e76189"]},
"OLAYLAR_ORTADOGU_0919:1819-08-13:0":{"b": ["Garnisun Mesir mundur dari Süleymiye di Harj dan mencapai Menfûha — Najd selatan tanpa pemimpin", "2743f70d"], "d": ["Setelah kehancuran Dir'iyah, pos Mesir yang ditempatkan İbrâhim Paşa di Süleymiye di Harj, sebelum berangkat atas perintah mundur sang Paşa, membunuh empat syekh Dilem dalam sebuah jamuan dan dikepung oleh suku Badui. Garnisun yang diselamatkan itu mencapai Menfûha pada 13 Agustus 1819 dan pawai ke Qasim dimulai. Di Najd selatan tidak tersisa otoritas pusat; upaya keluarga Saud tidak membuahkan hasil hingga 1824.", "fc53fbd1"]},
"OLAYLAR_P0043A:1456-01-01:0":{"b": ["Şehirköy kembali ke kekuasaan Utsmani — wafatnya Đurađ Branković", "e37156d1"], "d": ["Şehirköy, yang direbut tentara Salib pada 1443 dan ditinggalkan kepada Serbia oleh II. Murad setelah Perjanjian Edirne-Segedin 1444, kembali ke kekuasaan Utsmani dengan wafatnya Despot Serbia Đurađ Branković pada 1456. Pada tahun yang sama dan karena sebab yang sama Niş juga masuk ke administrasi Utsmani secara pasti; garis lembah Nišava yang terbuka ke jalan Sofia dengan demikian lengkap. Perjanjian itu ditandatangani untuk jangka sepuluh tahun, dan setelah Varna (1444) serta Kosovo II (1448), umur Despotat hanya sepanjang hidup Branković.", "4b6ec617"]},
"OLAYLAR_P0043B:1514-03-20:0":{"b": ["Yavuz Sultan Selim berangkat dari Edirne untuk Ekspedisi Çaldıran", "1f7921f7"], "d": ["Yavuz Sultan Selim, yang menunjuk putranya Şehzade Süleyman di Manisa sebagai wakilnya di İstanbul, berangkat dari Edirne untuk ekspedisi yang ia atur terhadap Negara Safawi. Tentara melintasi Anatolia lewat garis Sivas-Erzincan-Erzurum dan akan bertemu pasukan Şah İsmail di Çaldıran pada akhir Agustus.", "430f5ccc"]},
"OLAYLAR_P0043KIRIM:1526-01-01:0":{"b": ["Kızıkermen (Gazi Kerman) dan tepi kanan Dnieper masuk ke bawah kendali langsung Utsmani", "56a28224"], "d": ["Benteng Kızıkermen dan tepi kanan Dnieper, yang dikuasai Khanat Krimea sejak pertengahan abad ke-15, pada tanggal ini masuk ke bawah kendali langsung Negara Utsmani; benteng itu berubah menjadi pos terdepan Utsmani di ujung utara stepa. Berbeda dengan wilayah Khanat Krimea di sekitar Bahçesaray dan Or Kapı, administrasi Kızıkermen langsung di tangan Utsmani.", "a0eaba40"]},
"OLAYLAR_P0043KIRIM:1776-12-03:0":{"b": ["Prozorovski menduduki Or Kapı — pasukan Rusia tetap di Orkapı hingga aneksasi", "afdfe804"], "d": ["Ketika Jenderal Prozorovski, yang bergerak untuk menaikkan Şâhin Giray ke takhta Krimea, tiba di garis Perekop, Devlet Giray, kaymakam, dan bangsa Tatar telah mundur dari kota; Prozorovski menduduki benteng Or dan garis Perekop tanpa perang. Rusia menetap di Or Kapı dan tinggal di sana hingga aneksasi Krimea pada 1783.", "2c53b49b"]},
"OLAYLAR_P0043KIRIM:1791-07-26:0":{"b": ["Pendudukan Anapa oleh Rusia (pengepungan ketiga)", "e6a7d6d5"], "d": ["Benteng Anapa yang dibangun di bawah Ferah Ali Paşa pada 1781 dikepung Rusia tiga kali selama perang; pada akhir pengepungan ketiga, ia diduduki pada 26 Juli 1791. Pendudukan itu bersifat sementara — karena perbatasan lama di Kaukasus diterima dengan Perjanjian Yaş (1792), benteng dikembalikan kepada Negara Utsmani.", "6f3b16fa"]},
"OLAYLAR_P0043KIRIM:1828-06-24:0":{"b": ["Penyerahan Anapa oleh Osman Paşa kepada Rusia", "3ccbdd1d"], "d": ["Pada fase pembukaan Perang Utsmani-Rusia 1828-29, Anapa dikepung dan pasukan Utsmani di benteng di bawah komando Osman Paşa menyerah kepada Rusia pada 24 Juni 1828. Kali ini penyerahan bersifat permanen: dengan Perjanjian Edirne yang ditandatangani tahun berikutnya (14 September 1829), Anapa dan Kaukasus secara resmi lepas dari kekuasaan Utsmani.", "d49b4078"]},
"OLAYLAR_P0044:1556-01-01:0":{"b": ["Turgut Reis menjadi beylerbeyi Trablusgarp — eyalet meluas ke Tobruk dan Derne di timur", "160fa43c"], "d": ["Setelah penaklukan Trablusgarp pada 1551, Turgut Reis datang ke Trablusgarp dengan gelar beylerbeyi pada Cemâziyelevvel 963 (Maret 1556). Selama masa jabatannya yang berlangsung sembilan tahun, ia berupaya membangun dan membentengi eyalet, membawa administrasi Utsmani hingga Fizan di selatan, dan memperluas batas ke timur dengan merebut Tobruk dan Derne di pesisir Berka. Dengan demikian eyalet Trablusgarp mencakup jalur pantai hingga perbatasan Mesir.", "44cf4583"]},
"OLAYLAR_P0044:1556-01-01:1":{"b": ["Kekaisaran Moskow merebut Astrahan — Volga Hilir masuk ke kendali Rusia", "d02abd83"], "d": ["Pada 1556 Kekaisaran Moskow juga merebut Astrahan, sebuah langkah yang, dalam ungkapan TDV, 'akan membawa akibat yang sangat penting di masa depan'; dengan pendudukan Khanat Astrahan, Volga Hilir masuk ke kendali Rusia. Khan Krimea Devlet Giray ingin mencegah pendudukan ini tetapi tidak berhasil. Utsmani menjawab perkembangan ini dengan ekspedisi Astrahan pada 1569; tetapi karena tidak berhasil menguasai kawasan Volga Hilir, mereka menyerahkan perjuangan melawan Kekaisaran Moskow kepada khan Krimea.", "7e08ba29"]},
"OLAYLAR_P0044:1556-07-16:0":{"b": ["Penaklukan Kostayniçe dan Novi — dua benteng garis Una", "2093e452"], "d": ["Kostayniçe, yang dikepung Malkoç Bey pada musim panas 1556, dipertahankan oleh kapten Pankracije Lusthaller dengan lebih dari 60 prajurit; benteng diserahkan hanya sehari setelah pengepungan dimulai, pada 16 Juli, dan Lusthaller dituduh menjual benteng. Tak lama kemudian Novi juga direbut dan dibakar; dengan demikian dua benteng terpenting di Una jatuh ke tangan Utsmani dalam sekali pukul. Pada tahun yang sama di Wina didirikan Dewan Perang Istana (Hofkriegsrat) yang mengelola pertahanan serhad dari pusat.", "b985cbdf"]},
"OLAYLAR_P0044:1574-01-01:0":{"b": ["Mâku beralih ke Utsmani — Mahmûdî İvaz Bey ditugaskan membangun benteng", "5932ad38"], "d": ["Pada tahun 1574 Negara Utsmani menugaskan İvaz Bey, pemimpin suku Kurdi Mahmûdî, untuk merebut Mâku dari bangsa Iran dan membangun benteng di sana. Benteng di ujung timur eyalet Van ini memegang tempat penting dalam peristiwa yang terjadi di kawasan itu pada masa Utsmani.", "bd663d7c"]},
"OLAYLAR_P0044:1840-01-01:0":{"b": ["Uang kertas Utsmani pertama (kâime) diterbitkan", "d2e5e192"], "d": ["Dalam pencarian pendapatan bagi keuangan negara pada tahun-tahun pertama Tanzimat, atas usul Ârif Hikmet Bey yang kelak menjadi şeyhülislâm, penerapan kâime, bentuk yang disempurnakan dari sistem esham, diterima. Kâime pertama senilai total 160.000 lira (32.000 kese) diterbitkan dengan tulisan tangan tanpa menunggu dicetak karena kebutuhan uang yang mendesak, kemungkinan pada Juni 1840, pada masa Menteri Keuangan Sâib Paşa. Masa edar kertas-kertas yang berstatus uang tunai ini delapan tahun, bunganya 12,5% per tahun; tidak ada jaminannya, hanya bunganya yang dijamin dari pendapatan bea cukai İstanbul. Rakyat tidak menyambut baik uang yang tidak biasa itu, dan kâime tulisan tangan segera menjadi sasaran pemalsu.", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["Perebutan Malaka oleh Portugis", "e1556746"], "d": ["Malaka, yang didirikan pada 1390-an, telah menjadi pelabuhan tersibuk di kawasan itu dalam perdagangan laut antara Tiongkok, India, dan Barat, serta pusat Kesultanan Malaka, dan menjadi pusat utama penyebaran Islam ke pulau-pulau sekitarnya. Afonso de Albuquerque dari Portugal merebut kota itu pada 10 Agustus 1511; kota dijarah, dan masjid-masjid, makam dinasti, serta bangunan batu lainnya dihancurkan agar batunya dipakai membangun benteng. Malaka di bawah Portugis tak mampu mempertahankan keunggulan dagangnya yang lama; para pedagang muslim beralih ke pelabuhan Kesultanan Aceh di Sumatra. Atas serangan Portugis yang menetap di Malaka terhadap Aceh, sultan Aceh Alâeddin Riâyet Şah meminta bantuan Kanûnî Sultan Süleyman pada 1565.", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["Pernyataan kesetiaan Şâhverdi, penguasa Luristan, kepada Şah Abbas", "85791f94"], "d": ["Şâhverdi, penguasa Luristan yang pada 1589 tunduk kepada Utsmani dan menjadi bawahan beylerbeyi Bagdad, menurut penuturan sejarawan Safawi İskender Bey Münşî terpaksa menyatakan kesetiaan kepada mahkota Safawi pada tahun 1000 (1591-92). Sumber yang sama menulis bahwa pada tahun-tahun ini ia bolak-balik di antara kedua pihak, mengganggu para gubernur Hemedan dan melancarkan serbuan ke Burûcird, dan bahwa pada tahun 1002 (1593-94) Şah Abbas menduduki Hürremâbâd dan mengangkat seorang gubernur untuk kota itu. TDV İslâm Ansiklopedisi sebaliknya menempatkan penyatuan penuh Luristan, yang pada 1590 dihubungkan dengan administrasi Utsmani lewat Perjanjian İstanbul, kepada Safawi pada tahun 1603. Kedua tradisi memberi tanggal yang berbeda; butir ini menunjukkan pernyataan kesetiaan menurut tradisi Safawi, sedangkan butir 1603 menunjukkan kehilangan yang pasti. Di peta, dengan butir ini tidak ada perubahan pemilik: Luristan tampak di pihak Utsmani hingga 1603.", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["Peralihan pasti Luristan kepada Safawi", "4c5cf67b"], "d": ["Luristan, yang dihubungkan dengan administrasi Utsmani lewat Perjanjian İstanbul (Ferhad Paşa) 1590, dihubungkan sepenuhnya dengan Safawi oleh Şah I. Abbas pada 1603. Sejarawan Safawi İskender Bey Münşî sebaliknya menulis bahwa Hürremâbâd telah diduduki Şah Abbas lebih awal, pada tahun 1002 (1593-94), dan seorang gubernur Safawi diangkat untuk kota itu; perbedaan antara kedua tradisi ini belum terselesaikan. Pada tahun yang sama benteng Utsmani Nihâvend di utara Luristan juga jatuh ke tangan Şah Abbas; gubernur Hemedan Hasan Han meratakan benteng itu.", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["Kompi Katalan memasuki dinas Bizantium — awal ekspedisi Anatolia", "6623e7db"], "d": ["Kekaisaran Bizantium, yang kehilangan wilayah di hadapan beylik-beylik Turki di Anatolia Barat, menerima pasukan Katalan sekitar 6500 orang di bawah komando Roger de Flor sebagai tentara bayaran. Menurut artikel Bizans TDV, pasukan itu datang membantu kekaisaran pada 1303 dan pada tahun berikutnya menyelamatkan Alaşehir yang dikepung Germiyanoğulları. Namun kompi itu segera mulai menjarah tempat-tempat yang dilaluinya; Bizantium memindahkannya ke Trakia dan pada 1305 membunuh Roger de Flor.", "87b98a94"]},
"OLAYLAR_P0049:1538-11-27:0":{"b": ["Penguasa Hadramut dan Şihr mengakui kekuasaan Utsmani — kepulangan Hadım Süleyman Paşa dari ekspedisi India", "b5cb9363"], "d": ["Hadım Süleyman Paşa, yang kembali dari pengepungan Diu, singgah di Pelabuhan Şihr pada 27 November 1538; ketika penguasa Hadramut dan Şihr menerima kekuasaan Utsmani, ia melanjutkan ke Aden. Hadramut diorganisasi sebagai sancak yang bergantung pada Yaman, tetapi para pemimpin suku Kesîrî tetap memegang administrasi di kawasan itu. Ketundukan ini berlangsung hingga penarikan Utsmani dari Yaman pada 1635.", "cff04bbb"]},
"OLAYLAR_P0049:1555-05-29:0":{"b": ["Beylik Megrelya (Dadyan) ditinggalkan di zona pengaruh Utsmani", "ea54e8ea"], "d": ["Dengan ketentuan Perjanjian Amasya yang membagi Georgia, beylik Dadyan (Megrel dan Svanet) di Georgia Barat ditinggalkan di zona pengaruh Utsmani bersama İmereti dan Güryel. Di peta, Zugdidi, pusat Megrelya, sejak hari ini tampak sebagai beylik yang tunduk kepada Utsmani; pernyataan ketaatan yang sebenarnya akan datang pada 1578.", "1724aa10"]},
"OLAYLAR_P0049:1578-08-09:0":{"b": ["Atabeg Ahıska masuk ke administrasi Utsmani — Altunkale, Hırtıs, dan Ahılkelek", "024bb326"], "d": ["Segera setelah Lala Mustafa Paşa mengalahkan pasukan pelopor Safawi di Çıldır, wilayah yang berada di tangan atabeg Georgia juga beralih ke administrasi Utsmani. Dedis İmedi, yang menguasai Altunkale dan sekitarnya, bersama putra-putranya menyatakan ketaatan; sancak beyi Ardahan merebut Çıldır dan Tümük, sedangkan pasukan Utsmani lain merebut Hırtıs dan Ahılkelek. Sebuah sancak masing-masing ditinggalkan untuk Menûçihr dan saudaranya, sisa negeri atabeg dihubungkan dengan administrasi langsung. Ahıska sesudah itu akan menjadi pusat eyalet Çıldır yang baru dibentuk; Menûçihr, yang datang ke İstanbul, masuk Islam dan mengambil nama Mustafa, akan ditempatkan sebagai kepala eyalet ini pada 1 Juli 1579.", "23731679"]},
"OLAYLAR_P0049:1579-07-26:0":{"b": ["Kılıç Ali Paşa membangun Benteng Faş (Poti) — pangkalan Utsmani di muara Rioni", "f729ba95"], "d": ["Kaptan-ı derya Kılıç Ali Paşa membangun Benteng Faş di tempat sungai Rioni (Faş) bermuara ke Laut Hitam pada 26 Juli 1579.", "13606f9d"]},
"OLAYLAR_P0049:1587-01-01:0":{"b": ["Eyalet Gori didirikan — administrasi Utsmani langsung di barat Kartli", "9a7c8bc5"], "d": ["Pada 1578 para bey Georgia di kawasan Gori dan Muhran telah menaati Utsmani. Pada 1587 eyalet Gori didirikan di barat Kartli dan kawasan itu dihubungkan dengan administrasi Utsmani langsung. Benteng Gori, yang lepas pada pemberontakan Simon dari Georgia, direbut kembali pada 1601; administrasi Utsmani berakhir pada 1603 dengan ekspedisi Şah Abbas.", "7ee17c2b"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["Serbuan Mihail si Berani ke benteng-benteng Tuna — Rusçuk dibakar, İbrâil direbut, Silistre dijarah", "d0b83f6a"], "d": ["Voyvoda Eflak Mihail si Berani, yang bergabung dengan Liga Suci, pada musim dingin 1594-95 menyerbu benteng dan kota di tepi Tuna yang berada di bawah administrasi langsung Utsmani. Menurut artikel Rusçuk TDV, pada Februari 1595 ia tidak mampu merebut benteng tetapi menduduki kota dan membakarnya. Menurut artikel İbrâil, ia merebut İbrâil di tepi kiri Tuna dan kota itu tetap di tangannya hingga 1601; artikel III. Murad juga menulis bahwa tentara Eflak membakar benteng İbrâil dan mencapai Silistre. Menurut catatan tahrir yang disebut dalam artikel Silistre, tentara Eflak melintasi Tuna pada musim semi 1595 dan menjarah Silistre; benteng kota dihancurkan dan lama tidak dapat digunakan. Pada musim panas yang sama Koca Sinan Paşa akan berangkat ekspedisi ke Eflak.", "c115852f"]},
"OLAYLAR_P0049:1603-01-01:0":{"b": ["Şah Abbas merebut kembali Tiflis — berakhirnya administrasi Utsmani di Kartli dan Kakheti", "a6995ea8"], "d": ["Şah I. Abbas merebut kembali Tiflis dari Utsmani pada 1603 dan memproklamasikan Kartli sebagai khanat; di Kakheti pun ditegakkan administrasi Safawi. Dengan demikian administrasi Utsmani di Georgia Timur, yang dimulai dengan ekspedisi Lala Mustafa Paşa pada 1578, berakhir; Tiflis baru akan jatuh kembali ke tangan Utsmani pada 1723.", "e37dcbfc"]},
"OLAYLAR_P0049:1640-01-01:0":{"b": ["Benteng Faş (Poti) dihancurkan oleh pasukan İmereti, Guria, dan Megrelya", "3c3d4ed7"], "d": ["Benteng Faş diratakan pada 1640 oleh pasukan İmereti yang diikuti para pangeran Guria dan Megrelya. Kehadiran Utsmani di muara Rioni terputus hingga benteng dibangun kembali pada 1724.", "2bb31f58"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["Ekspedisi Prut dimulai — dalam Perang Utsmani-Rusia 1710-1711, tentara berangkat dari İstanbul", "3161364b"], "d": ["Serangan Rusia ke wilayah Utsmani, pelanggaran Tsar Petro terhadap ketentuan Perjanjian İstanbul 1700, dan dorongan Khan Krimea Devlet Giray telah membawa III. Ahmed untuk menyatakan perang terhadap Rusia. Menurut artikel III. Ahmed TDV, perang yang kemudian disebut Ekspedisi Prut ini secara nyata dimulai dengan keberangkatan tentara Utsmani dari İstanbul pada 9 April 1711. Tentara di bawah Baltacı Mehmed Paşa bergabung dengan pasukan Krimea dan maju menuju sungai Prut; ekspedisi akan berakhir pada Juli dengan terkepungnya tentara Rusia di tepi Prut.", "49618c54"]},
"OLAYLAR_P0049:1724-03-01:0":{"b": ["Pembangunan kembali Benteng Faş (Poti) dimulai", "0afbc4b0"], "d": ["Dengan keputusan 23 Desember 1723, pembangunan kembali Benteng Faş yang runtuh dimulai pada Maret 1724; pembangunan selesai pada 1729.", "e9e6b3d8"]},
"OLAYLAR_P0049:1724-05-06:0":{"b": ["Kawasan Hoy, Kapan, dan Karadağ kembali masuk ke administrasi Utsmani", "c52c94d1"], "d": ["Selama ekspedisi Iran yang dimulai pada 1723, Hoy bersama kawasan Kapan dan Karadağ kembali masuk ke administrasi Utsmani pada 6 Mei 1724 dan dicatat dalam tahrir Utsmani pada 1728. Atlas menganggap Kotur, 40 km di barat daya Hoy, juga beralih dari Safawi ke Utsmani pada hari ini (rantai diwarisi dari Hoy: Uluerler 2015, Turkish Studies 10/5, hlm. 6; hari khusus untuk Kotur tidak ada dalam sumber — pendekatan yang dinyatakan).", "eb5141eb"]},
"OLAYLAR_P0049:1733-08-17:0":{"b": ["Nâdir memasuki Şemâhî — pusat Şirvan lepas dari Utsmani", "778a4988"], "d": ["Nâdir memasuki Şemâhî, yang jatuh ke bagian Utsmani bersama bagian tengah Şirvan berdasarkan Muahedesi İstanbul 24 Juni 1724, pada 17 Agustus 1733. Administrasi Utsmani di Kaukasus sesudahnya dengan cepat runtuh; Gence dan Tiflis lepas pada 1735.", "4ab61a36"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Ultimatum kepada duta Rusia — langkah terakhir menuju Perang Utsmani-Rusia 1787-1792", "cb389693"], "d": ["Ketegangan yang berlanjut sejak aneksasi Krimea oleh Rusia pada 1783 putus ketika diketahui bahwa konsulat Rusia di Iskandariyah menghasut para bey kölemen di Mesir melawan Utsmani. Menurut artikel I. Abdülhamid TDV, Reîsülküttâb Süleyman Feyzi Efendi memberikan ultimatum tujuh pasal kepada duta Rusia di İstanbul pada 27 Juli 1787. Keputusan perang diambil tanpa menunggu jawaban Rusia dan diumumkan dalam beberapa pekan; sasaran perang adalah merebut kembali Krimea.", "04debfa8"]},
"OLAYLAR_P0049:1809-11-27:0":{"b": ["Pasukan Rusia merebut Benteng Faş (Poti) — muara Rioni lepas", "c1241b5a"], "d": ["Selama perang Utsmani-Rusia 1806-1812, serangan Rusia pada Mei 1809 gagal; namun benteng diserahkan kepada Rusia pada 27 November 1809.", "84e0aac2"]},
"OLAYLAR_P0049:1812-12-19:0":{"b": ["Berdasarkan Perjanjian Bükreş, Benteng Faş (Poti) dikembalikan kepada Utsmani", "6a3a8a0a"], "d": ["Berdasarkan Perjanjian Bükreş 1812, Benteng Faş diserahkan kepada Negara Utsmani pada 19 Desember 1812.", "d59bceb8"]},
"OLAYLAR_P0049:1828-06-26:0":{"b": ["Benteng Faş (Poti) jatuh ke tangan Rusia untuk kedua kalinya — tetap di Rusia dengan Perjanjian Edirne", "682d58f0"], "d": ["Pada awal perang Utsmani-Rusia 1828-1829, Benteng Faş diserahkan kepada Rusia pada 26 Juni 1828. Dengan Perjanjian Edirne 14 September 1829, Poti bersama Ahıska, Ahılkelek, dan Anapa diserahkan kepada Rusia.", "364c160c"]},
"OLAYLAR_P0049:1915-07-25:0":{"b": ["Inggris menduduki Nâsıriye — front Efrat", "669b979e"], "d": ["Pasukan Inggris yang maju dari Basra menyusuri Efrat mengalahkan pasukan Utsmani pada 24 Juli 1915 dan menduduki Nâsıriye keesokan harinya. Basra telah jatuh pada November 1914; Nâsıriye tetap di tangan Utsmani sekitar delapan bulan lagi.", "bd125229"]},
"OLAYLAR_P0049:1919-04-12:0":{"b": ["Pendudukan Kars oleh Inggris — Pemerintah Kaukasus Barat Daya dibubarkan", "9004afc9"], "d": ["Sesuai ketentuan Gencatan Senjata Mondros tentang penarikan ke perbatasan 1914, tentara Utsmani telah mengosongkan Kars. Rakyat kawasan itu mendirikan Dewan Islam Kars pada 5 November 1918 terhadap serangan Armenia dan Georgia, dan dengan kongres Januari 1919 mengubahnya menjadi Cenûb-ı Garbî Kafkas Hükûmet-i Muvakkate-i Milliyesi. Menurut artikel Kars TDV, Inggris menduduki Kars pada 12 April 1919 dan membubarkan pemerintahan ini, menangkap anggotanya dan mengirim mereka ke pengasingan, serta menyerahkan kendali kota kepada bangsa Armenia.", "06392190"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Pendudukan Antalya oleh Italia", "328331da"], "d": ["Setelah Gencatan Senjata Mondros, ketika negara-negara Entente menempati zona pendudukan di Anatolia, Italia mengarah ke Anatolia barat daya. Menurut artikel Antalya TDV, kota dan sekitarnya diduduki Italia pada 29 April 1919 dengan bersandar pada ketentuan gencatan senjata. Pendudukan itu akan berlangsung sekitar dua tahun.", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Pembebasan Maraş — Prancis mengosongkan kota", "a57d884e"], "d": ["Maraş, yang diduduki Inggris pada 22 Februari 1919, diserahkan kepada Prancis pada 29 Oktober 1919 berdasarkan kesepakatan kedua negara. Sikap bangsa Armenia dalam pasukan Prancis dan penurunan bendera Turki di benteng membangkitkan perlawanan rakyat; di kota dibentuk Müdâfaa-i Hukuk Cemiyeti dan Kuvâ-yi Milliye. Menurut artikel Kahramanmaraş TDV, pada akhir pertempuran Prancis mengosongkan kota pada 11 Februari 1920 dan mulai mundur ke arah İslâhiye, dan Maraş dibebaskan pada 11-12 Februari. Kota itu dianugerahi medali İstiklâl pada 1925.", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Pembebasan Urfa — garnisun Prancis meninggalkan kota", "c889488c"], "d": ["Di Urfa, yang diduduki Inggris pada Maret 1919 dan sekitar tujuh bulan kemudian oleh Prancis, rakyat bangkit melawan pasukan pendudukan pada 7 Februari 1920. Menurut artikel Şanlıurfa TDV, setelah pertempuran dua bulan Prancis setuju mengosongkan Urfa dengan syarat perjanjian pada 10 April 1920 dan keluar dari kota keesokan harinya.", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["Operasi Front Timur dimulai — Kâzım Karabekir melancarkan serangan terhadap Armenia", "151678df"], "d": ["Ketika Perjanjian Sevr menyerahkan Erzurum, Trabzon, Van, Bitlis, dan Bingöl kepada Armenia dan serangan Armenia di kawasan meningkat, pemerintah TBMM mengizinkan operasi pada 20 September 1920. Menurut artikel Kâzım Karabekir TDV, Karabekir, Komandan Front Timur (Şark Cephesi), memberi perintah serangan kepada pasukannya yang menguasai celah gunung Soğanlı dan memulai operasi timur pada 28 September. Sarıkamış, Göle, dan Kağızman direbut; operasi akan berlanjut sebulan kemudian dengan pembebasan Kars.", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Pembebasan Kars — Front Timur memasuki Kars", "4e578071"], "d": ["Menurut artikel Kars TDV, Kâzım Karabekir Paşa memasuki Kars pada 30 Oktober 1920, dan kota itu dibebaskan dari administrasi Armenia yang kendalinya ditinggalkan Inggris pada 1919. Artikel Karabekir menekankan bahwa ini adalah pembebasan kedua Kars: kota itu pertama kali direbut dari bangsa Armenia pada April 1918. Front Timur maju dan merebut Gümrü pada 7 November; perang berakhir dengan Perjanjian Gümrü pada 3 Desember 1920.", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Perebutan Gümrü — Front Timur maju ke pedalaman Armenia", "cfddf791"], "d": ["Pasukan Kâzım Karabekir Paşa, yang melanjutkan operasi setelah pembebasan Kars, merebut Gümrü pada 7 November 1920. Perundingan dengan bangsa Armenia yang menyetujui gencatan senjata dilakukan di Gümrü, dan perang berakhir dengan Perjanjian Gümrü yang ditandatangani pada 3 Desember 1920.", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Perebutan Iğdır", "6e952d2e"], "d": ["Lima hari setelah merebut Gümrü, pada 12 November 1920, Front Timur juga merebut Iğdır. Iğdır diserahkan kepada Turki dengan Perjanjian Gümrü 3 Desember 1920.", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Akhir pertahanan Antep — kota ditinggalkan kepada Prancis setelah bertahan sepuluh bulan", "e080af8b"], "d": ["Antep, yang dimasuki Inggris pada 17 Desember 1918, ditinggalkan kepada Prancis pada 5 November 1919; perlawanan pertama di garis Antep-Kilis dipimpin Şâhin Bey. Menurut artikel Gaziantep TDV, rakyat kota melawan pasukan Prancis dari 1 April 1920 hingga 7 Februari 1921; ketika perlawanan patah, pasukan pembela mundur dan Prancis menguasai kota pada 9 Februari. TBMM telah memberikan gelar gazi kepada kota yang bertahan sepuluh bulan melawan pendudukan itu tiga hari sebelumnya, pada 6 Februari 1921. Antep akan dikosongkan pada 25 Desember 1921 setelah Perjanjian Ankara.", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Pembebasan Ardahan dan Artvin", "b9e50d5e"], "d": ["Setelah Perjanjian Gümrü, Front Timur mengarah ke bagian elviye-i selâse yang berada di tangan Georgia. Menurut artikel Ardahan TDV, pada akhir perjuangan melawan pasukan gerilya Georgia dan Armenia, sancak Ardahan bersama Artvin dibebaskan pada 23 Februari 1921. Artikel Kâzım Karabekir menulis bahwa dengan langkah ini wilayah elviye-i selâse di luar kaza Çürüksu, Acara, dan Batum direbut kembali.", "1ee51ba4"]},
"OLAYLAR_P0049:1921-03-16:0":{"b": ["Perjanjian Moskow — TBMM dan Rusia Soviet menetapkan perbatasan timur", "78d46573"], "d": ["Perjanjian Moskow ditandatangani antara pemerintah TBMM dan Rusia Soviet pada 16 Maret 1921. Menurut artikel Kars TDV, dengan perjanjian ini dan hasil pengaturan perbatasan Perjanjian Kars 13 Oktober 1921, Kars tetap berada dalam batas negara Turki yang baru. Menurut artikel Ahıska, dengan perjanjian ini Ahıska dihubungkan dengan vilayet Tiflis dari Republik Sosialis Soviet Georgia. Perbatasan timur akan dipastikan oleh Perjanjian Kars yang ditandatangani tujuh bulan kemudian dengan republik-republik Kaukasus Selatan. Dengan perjanjian ini Batum dan Acara (Hulo, Sarp, Murvaneti, Makhalak'auri) ditinggalkan kepada Georgia Soviet.", "7951b57b"]},
"OLAYLAR_P0049:1921-06-01:0":{"b": ["Italia mulai mengosongkan Antalya", "f7a4eaa7"], "d": ["Menurut artikel Antalya TDV, pendudukan Italia yang berlangsung sejak 29 April 1919 berakhir ketika Italia mulai mengosongkan kota pada 1 Juni 1921. Antalya dan sekitarnya dengan demikian terbebas dari pendudukan tanpa menunggu hasil militer Perjuangan Nasional.", "ffd82d73"]},
"OLAYLAR_P0050:1527-01-01:0":{"b": ["Dewan Cetin — bangsawan Kroasia memilih Ferdinand dari Habsburg sebagai raja Kroasia setelah Mohaç", "55fc9d7e"], "d": ["Ketika takhta kosong dengan wafatnya II. Lajos, raja Hongaria-Kroasia, di Mohaç, bangsawan Kroasia berkumpul di Cetin pada 31 Desember 1526 dan pada hari tahun baru menyatakan Ferdinand, arsiduke Austria, sebagai raja. Dalam ungkapan TDV, bangsa Kroasia melakukan pemilihan ini terlepas dari bangsawan Hongaria; dokumen pemilihan bersandar pada alasan tidak memisahkan diri dari negara Kristen di hadapan serbuan Utsmani. Dengan demikian benteng-benteng Kroasia yang bertetangga dengan Bosnia Utsmani terikat pada mahkota dinasti Habsburg; menurut TDV, ketika Habsburg mulai menata kawasan perbatasan Kroasia pada 1530-an, pusat utama garis ini adalah Bihaç.", "5e7c69d8"]},
"OLAYLAR_P0050:1527-01-01:1":{"b": ["Administrasi Utsmani singkat atas Bihaç — setelah jatuhnya Mohaç dan Yayça", "fd4118fe"], "d": ["Setelah kemenangan Mohaç, Utsmani merebut Yayça, pusat zona penyangga Hongaria di Bosnia, dan Banaluka. Menurut artikel Bihaç TDV, setelah direbutnya Benteng Yayça pada tahun yang mengikuti Mohaç, Bihaç untuk waktu singkat kembali ke administrasi Utsmani. Sumber tidak menulis kapan dan bagaimana benteng itu lepas; TDV hanya menyebutkan bahwa pada 1530-an, ketika menata kawasan perbatasan Kroasia, Habsburg menjadikan Bihaç yang berada di tangan orang Kristen sebagai pusat utama. Penaklukan Bihaç yang permanen akan terwujud pada 1592 dengan ekspedisi Beylerbeyi Bosnia Hasan Paşa.", "3421f09a"]},
"OLAYLAR_P0050:1814-01-28:0":{"b": ["Berakhirnya administrasi Prancis di Dubrovnik — pasukan Austria memasuki kota bekas pembayar upeti Utsmani", "38d42444"], "d": ["Menurut TDV, Republik Dubrovnik yang berada di bawah perlindungan Utsmani sejak 1365 diakhiri oleh Prancis dengan merebut kota pada 27 Mei 1806. Pada musim dingin 1813-1814 rakyat kota bangkit melawan Prancis; pada 3 Januari 1814 mayor jenderal Austria Milutinović, yang datang ke Gruž dengan dua batalion Kroasia, mengepung garnisun; setelah pengeboman empat hari, garnisun Prancis mengirim utusan kepada sang jenderal. Pada fajar 28 Januari pasukan Austria dan Inggris berbaris dari Gruž ke kota; pada 31 Januari administrasi Austria sementara mulai bekerja di kawasan itu. Bergabungnya kota ke wilayah Austria dipastikan pada Kongres Wina 1815.", "bb94e4af"]},
"OLAYLAR_P0050:1882-03-06:0":{"b": ["Proklamasi Kerajaan Serbia — kepangeranan bawahan Utsmani lama berubah menjadi kerajaan", "7d90e712"], "d": ["Kepangeranan Serbia, yang meraih kemerdekaan pada 1878 dan pada tahun yang sama juga merebut Niş yang berada di tangan Utsmani, diubah menjadi kerajaan pada masa Milan Obrenović. Dengan pasal pertama undang-undang yang dikeluarkan di Belgrade, kepangeranan diproklamasikan sebagai Kerajaan Serbia dan Pangeran Milan menjadi raja dengan nama Milan I; undang-undang itu diterbitkan pada hari yang sama di surat kabar resmi Srpske novine. Dengan demikian Serbia, yang hingga 1878 adalah kepangeranan yang bergantung pada Utsmani, mengambil tempatnya di Balkan dengan gelar kerajaan. Dengan proklamasi ini seluruh Kepangeranan Serbia (Belgrade, Niş, Yagodina, İvranye, Leskofça, Ürküp, Şehirköy, dll.) menjadi Kerajaan Serbia.", "a2849d70"]},
"OLAYLAR_P0050:1920-07-01:0":{"b": ["Administrasi mandat sipil Inggris didirikan di Palestina — akhir pemerintahan militer di wilayah yang diambil dari Utsmani", "c0d7b76a"], "d": ["Dengan direbutnya Gaza dan kemudian Yerusalem oleh Jenderal Allenby pada 1917, kekuasaan Utsmani empat ratus tahun di Palestina berakhir, dan Yerusalem tetap di bawah pemerintahan militer Inggris antara 1917 dan 1920. Konferensi San Remo 1920 menyerahkan Palestina kepada mandat Inggris; sejak Juli 1920 Inggris mendirikan administrasi mandat sipil di kawasan itu dan mulai memerintah negeri itu melalui seorang komisaris tinggi. Komisaris tinggi Herbert Samuel berada di puncak administrasi sipil. Pemberontakan Arab dan bentrokan Yahudi-Arab yang dimulai pada tahun yang sama akan menandai seluruh masa mandat. Dengan peristiwa ini Tiberias (Palestina) beralih ke administrasi mandat sipil Inggris.", "bc1ec892"]},
"OLAYLAR_P0050:1922-03-15:0":{"b": ["Kerajaan Mesir diproklamasikan — Sultan Ahmed Fuâd mengambil gelar raja", "c6ad08d1"], "d": ["Inggris pada 18 Desember 1914 secara sepihak menghapus hak kedaulatan Negara Utsmani atas Mesir dan menempatkan negeri itu di bawah perlindungannya. Setelah perang, ketika perundingan antara Inggris dan Mesir tidak membuahkan hasil, Inggris pada 28 Februari 1922 kembali dengan pernyataan sepihak menyatakan Mesir sebagai negara merdeka. Sultan Ahmed Fuâd mengambil gelar raja (melik) pada 15 Maret 1922 dan monarki diproklamasikan di Mesir. TDV menganggap kemerdekaan ini bersifat formal; konstitusi tatanan kerajaan akan berlaku pada 19 April 1923.", "f9b00023"]},
"OLAYLAR_P0051:1480-01-01:0":{"b": ["Lepasnya benteng Hacıbey (Kaçibey) dari tangan Lituania", "382b51e3"], "d": ["Pelabuhan Kaçibey di pesisir barat laut Laut Hitam telah dibentengi oleh adipati agung Lituania Vytautas pada awal abad ke-15. Pada 1480 benteng lepas dari tangan Lituania dan mengambil nama Hacıbey. Pesisir itu pada akhir abad ke-15 masuk ke kendali Khanat Krimea yang tunduk pada Utsmani; penghubungan kawasan itu dengan organisasi administratif Utsmani secara langsung terjadi pada 1538.", "cea3442c"]},
"OLAYLAR_P0051:1570-01-01:0":{"b": ["Gramota IV. Ivan kepada Kazak Don — catatan tepercaya pertama Orda Kazak Don", "16c0732e"], "d": ["Informasi tentang keberadaan Kazak di Don dimulai sejak pertengahan abad ke-16. Menurut ensiklopedia militer Rusia, senioritas Orda Kazak Don dihitung dari 1570: pada tahun itu Tsar IV. Ivan mengirim gramota kepada Kazak yang hidup di Donets Utara, meminta mereka membantu Ivan Novosiltsev yang dikirim sebagai utusan lewat Azak kepada sultan Utsmani, dan menjanjikan imbalan. Ini adalah catatan tepercaya pertama tentang pengabdian Kazak Don kepada negara Moskow. Pusat utama Kazak mula-mula Razdory Atas, kemudian Çerkassk.", "3ce37828"]},
"OLAYLAR_P0051:1585-01-01:0":{"b": ["Moskow mendirikan garnisun terdepan di Voronezh menghadapi stepa", "89c941fe"], "d": ["Pada akhir abad ke-16, Sloboda Ukraina masa kini dan daerah aliran atas Don adalah stepa liar yang sepi, tempat bangsa Tatar melintas dalam serbuan ke Moskow. Pemerintah Moskow mendirikan serangkaian garnisun terdepan di stepa ini; Voronezh didirikan sebagai salah satunya pada 1585. Benteng ini, bersama Belgorod dan Kursk, menjadi mata rantai pertama garis pertahanan selatan Moskow pada dekade-dekade berikutnya.", "ceb11b6b"]},
"OLAYLAR_P0051:1596-01-01:0":{"b": ["Moskow mendirikan Belgorod, Oskol, dan Kursk sebagai garnisun terdepan di stepa", "4ff3e225"], "d": ["Pemerintah Moskow memajukan perbatasan selatan terhadap serbuan Krimea dan pada 1596 mendirikan Belgorod, Oskol, dan Kursk sebagai titik garnisun di stepa liar. Belgorod sejak tanggal ini menjadi kota benteng dan menjadi pusat garis pertahanan Belgorod sepanjang 300 kilometer yang akan membentang pada abad berikutnya.", "50cb899c"]},
"OLAYLAR_P0052:1884-01-01:0":{"b": ["Sancak Siirt dipindahkan dari Diyarbekir ke vilayet Bitlis — kaza Eruh dan desa Şırnak juga dihubungkan dengan Bitlis", "3922d040"], "d": ["Ketika beralih dari sistem eyalet ke sistem vilayet setelah Tanzimat, sancak Siirt yang tetap bergantung pada vilayet Diyarbekir dipindahkan ke vilayet Bitlis pada 1884. Menurut artikel Şırnak TDV, tanah tempat Şırnak masa kini berada dengan demikian juga berada dalam kaza Eruh yang bergantung pada sancak Siirt vilayet Bitlis. Pada saat itu Şırnak adalah desa kecil kaza Eruh; namanya tampak dalam catatan menjelang akhir abad XIX, sedangkan statusnya sebagai pusat kaza baru terjadi pada tahun-tahun awal Republik. Tanah-tanah ini telah bergabung ke Utsmani pada 1514 setelah Ekspedisi Çaldıran dan diadministrasikan dalam sancak Siirt eyalet Diyarbekir.", "1539b089"]},
"OLAYLAR_P0053:1624-01-01:0":{"b": ["Mosul dan Kirkuk jatuh ke tangan Safawi — setelah jatuhnya Bagdad", "86e176c8"], "d": ["Şah Abbas, yang merebut Bagdad pada akhir peristiwa yang dimulai dengan pemberontakan Bekir Subaşı, mengirim komandannya Karçakay Han dengan pasukannya ke Mosul dan Kirkuk. Gubernur Mosul Çerkez Ahmed Paşa hanya dapat mempertahankan kota beberapa hari; seperti Kirkuk, Mosul jatuh ke kekuasaan Iran dan Kāsım Han ditunjuk sebagai gubernur. Ketika Sipahi Küçük Ahmed, yang memimpin pasukan pelopor Hâfız Ahmed Paşa, tampak di depan Mosul, Kāsım Han meninggalkan kota dan mundur ke Bagdad, tetapi dengan operasi balasan Şah Abbas Mosul kembali jatuh ke tangan Safawi pada 1624.", "81474bd6"]},
"OLAYLAR_P0053:1625-01-01:0":{"b": ["Pembebasan Mosul dari Safawi — ekspedisi Bagdad Hâfız Ahmed Paşa", "1f9ca4a1"], "d": ["IV. Murad mengirim tentara di bawah Vezîriâzam Hâfız Ahmed Paşa ke Bagdad. Ketika tentara berada di sekitar Diyarbekir, pasukan pelopor Beylerbeyi Karaman Çerkez Hasan mengejar para pendukung Iran yang berkumpul di Altınköprü hingga Kirkuk dan menguasai kawasan termasuk Kirkuk; Safawi kali ini pun tidak dapat menahan Mosul untuk waktu lama. Hâfız Ahmed Paşa pada awal September tiba pertama di Mosul, kemudian di Kirkuk, dan mengepung Bagdad pada 13 November 1625; pengepungan tidak membuahkan hasil dan Bagdad tetap di tangan Safawi. Artikel Kirkuk TDV sebaliknya mengaitkan direbutnya kembali kota dari Safawi dengan Hüsrev Paşa pada 1630.", "ad32f3ae"]},
"OLAYLAR_P0053:1630-03-16:0":{"b": ["Hüsrev Paşa membangun kembali Benteng Gülanber di Şehrizor — beylerbeyilik Şehrizor", "9511853c"], "d": ["Sadrazam Hüsrev Paşa, yang berangkat ke ekspedisi Bagdad, setelah lama tinggal di Mosul karena hujan lebat mengarah ke Şehrizor. Pembangunan kembali Benteng Gülanber, yang dirobohkan atas perintah Şah Abbas pada invasinya, dimulai; Şehrizor dijadikan lagi pusat beylerbeyilik dan Arnavud Mustafa Paşa ditinggalkan di benteng sebagai beylerbeyi. Hüsrev Paşa menundukkan suku-suku di kawasan itu, merebut Benteng Mihriban, dan pada 5 Mei 1630 menimbulkan kerugian berat pada tentara Safawi di dekat benteng ini.", "ff2c7cea"]},
"OLAYLAR_P0055:1369-01-01:0":{"b": ["Timurtaş Bey merebut Kızılcaağaç Yenicesi (Elhova) dan Yanbolu di lembah Tunca", "2c2aebea"], "d": ["Selama operasi I. Murad terhadap Bulgaria dan Bizantium, Kara Timurtaş Bey dikirim ke lembah Tunca; ia merebut Kızılcaağaç Yenicesi dan Yanbolu serta kembali ke Edirne dengan banyak rampasan.", "e2ca7962"]},
"OLAYLAR_P0055:1371-09-26:0":{"b": ["Kepangeranan Dejanović (Kostadin-ili) menjadi vasal Utsmani", "54b8dd6c"], "d": ["Ketika negara Serbia pecah dengan kekalahan Meriç (Çirmen), dua bersaudara Jovan dan Konstantin Dejanović mendirikan kepangeranan mereka sendiri yang berpusat di Velbujd (kemudian bernama Köstendil) dan mencakup İştip, Ustrumca, Doyran, dan kawasan Köprülü. Dengan wafatnya Jovan tak lama kemudian, Konstantin mengakui kekuasaan I. Murad dan menjadi vasal Utsmani; kepangeranan hidup semi-merdeka dengan ikatan ini. Ketika Konstantin gugur di barisan Yıldırım Bayezid di Rovine pada 1395, negerinya masuk ke administrasi Utsmani tanpa perang dan menjadi sancak dengan nama Kostadin-ili.", "25fd68b1"]},
"OLAYLAR_P0055:1412-01-01:0":{"b": ["Despot Serbia Stefan Lazarević merebut Şehirköy (Pirot)", "87e1ecb3"], "d": ["Ketika perjuangan antara Mûsâ Çelebi, yang menguasai Rumeli pada Masa Fetret, dan saudaranya Çelebi Mehmed berlanjut, Despot Serbia Stefan Lazarević merebut benteng Şehirköy yang terletak di jalan antara Niş dan Sofia, dan mempertahankannya terhadap serangan Mûsâ Çelebi. Pada tahun berikutnya dengan wafatnya Mûsâ, Çelebi Mehmed secara resmi menyerahkan benteng kepada vasalnya Stefan; Utsmani baru merebut kembali Şehirköy pada 1428 setelah wafatnya Lazarević.", "f50a8066"]},
"OLAYLAR_P0055:1538-01-01:0":{"b": ["Herseknovi (Castelnuovo) direbut oleh Andrea Doria", "a8276ff1"], "d": ["Andrea Doria, komandan armada sekutu yang bersatu melawan Utsmani, merebut benteng Herseknovi (Castelnuovo) di pesisir Adriatik, di selatan Dalmatia. Pada tahun yang sama di Dalmatia bangsa Venesia juga merebut beberapa kota yang berada di tangan Utsmani, dan pasukan Utsmani membalas dengan benteng-benteng lain. Benteng direbut kembali setahun kemudian; karena kedaulatan Utsmani secara hukum berlanjut, masa selingan ini ditunjukkan di peta dengan lapisan pendudukan yang diarsir.", "a9462728"]},
"OLAYLAR_P0055:1539-08-10:0":{"b": ["Perebutan kembali Herseknovi (Castelnuovo) oleh Barbaros Hayreddin Paşa", "1e5b49ae"], "d": ["Utsmani, yang setelah kemenangan Preveze juga meraih keunggulan di Mediterania Tengah, mengarah ke benteng Nova (Castelnuovo) di pesisir Adriatik yang direbut Andrea Doria setahun sebelumnya. Pada akhir operasi yang dijalankan bersama oleh Barbaros Hayreddin Paşa dan Bey Bosnia Gazi Hüsrev Bey, benteng direbut kembali dan pendudukan berakhir.", "29e2c28b"]},
"OLAYLAR_P0055:1798-12-25:0":{"b": ["Ekspedisi Mesir Hulu Desaix — divisi Prancis mencapai Minye, Asyut, dan Girga", "8ff8e4fe"], "d": ["Ketika Napoleon berada di Kairo, divisi Jenderal Desaix mengejar pasukan Mamluk dan maju ke selatan di lembah Nil: tiba di Minye pada 21 Desember 1798, di Asyut pada hari Natal, dan di Girga pada 29 Desember. Dengan pawai ini yang mencapai Aswan pada Februari 1799, lembah antara Kairo dan Aswan masuk ke kendali Prancis.", "96ddd684"]},
"OLAYLAR_P0055:1799-02-18:0":{"b": ["Napoleon menduduki Arîş — awal ekspedisi Suriah", "69dc52ce"], "d": ["Tentara Prancis yang menduduki Mesir merebut Arîş di pesisir Sinai ketika berbaris ke Suriah.", "8feb359c"]},
"OLAYLAR_P0055:1799-12-28:0":{"b": ["Perebutan kembali Arîş dari Prancis", "c25e48a7"], "d": ["Arîş, yang diduduki Napoleon pada Februari 1799, direbut kembali oleh tentara Sadrazam Yûsuf Ziyâ Paşa pada akhir Desember tahun yang sama.", "3bde687a"]},
"OLAYLAR_P0056:1739-08-28:0":{"b": ["Kekalahan Stavuçani dan penyerahan Hotin kepada Rusia (Perang Utsmani-Rusia 1736-1739)", "657d82d2"], "d": ["Dalam ekspedisi 1739, tentara utama Rusia di bawah komando Marsekal Münnich melintasi wilayah Polandia dan memasuki Boğdan, dan menimbulkan kekalahan berat pada tentara Serasker Veli Paşa di Stavuçani dekat Hotin. Segera setelah pertempuran ini benteng Hotin menyerah kepada Rusia dan pasukan Rusia memasuki Yaş pada awal September. Namun karena Austria membuat perdamaian terpisah, perang berakhir dengan Perjanjian Belgrade yang ditandatangani pada bulan yang sama.", "2e7457b9"]},
"OLAYLAR_P0056:1769-01-01:0":{"b": ["Tentara Rusia melintasi Dniester dan memasuki Boğdan (Perang Utsmani-Rusia 1768-1774)", "938bd834"], "d": ["Sekitar enam bulan setelah deklarasi perang, tentara utama Rusia berkumpul di Podolia di bawah komando Pangeran Golitsin. Atas seruan metropolit Boğdan Dositey untuk menempatkan Moldova di bawah perlindungan Rusia, Golitsin melintasi Dniester dan mencoba merebut Hotin sebelum berbaris ke Yaş. Percobaan pertama ini gagal, tentara kembali ke Podolia karena kekurangan perbekalan; Hotin baru jatuh pada September 1769.", "df52a8ec"]},
"OLAYLAR_P0056:1788-01-01:0":{"b": ["Tentara Ukraina Rusia melintasi Dniester di Mogilev dan memasuki Boğdan (Perang Utsmani-Rusia 1787-1792)", "822c7361"], "d": ["Dalam perang yang dimulai dengan deklarasi perang Utsmani pada 1787, Rusia membentuk dua tentara: tentara Potemkin mengepung Özi, sedangkan tentara Ukraina Rumyantsev akan mengancam Bender antara Dniester dan Bug serta menjaga hubungan dengan Austria. Rumyantsev memisahkan satu kolom untuk mendukung bangsa Austria yang mengepung Hotin, dan dengan pasukan utamanya melintasi Dniester di Mogilev dan memasuki Boğdan. Dengan demikian dimulailah cabang Boğdan dari operasi Rusia yang akan meluas hingga İsmail dan Tuna.", "7c701213"]},
"OLAYLAR_P0056:1806-11-23:0":{"b": ["Tentara Rusia melintasi Dniester tanpa deklarasi perang dan mulai menduduki Memleketeyn (Perang Utsmani-Rusia 1806-1812)", "2094a4d9"], "d": ["Pada Oktober 1806 Jenderal Michelson diperintahkan menduduki Boğdan dan Eflak; perang belum diumumkan secara resmi. Pasukan Rusia mulai melintasi Dniester dan para komandan benteng Hotin, Bender, Akkirman, dan Kili menyerahkan benteng mereka tanpa pertempuran. Hanya komandan İsmail yang tidak tunduk pada bujukan Rusia. Deklarasi perang Bâbıâli datang setelah pendudukan ini.", "c770c2b4"]},
"OLAYLAR_P0056:1806-11-30:0":{"b": ["Perebutan Akkirman oleh Rusia (1806)", "25aed8d6"], "d": ["Seminggu setelah tentara Rusia melintasi Dniester tanpa deklarasi perang, Akkirman direbut oleh pasukan Pangeran Kantakuzino; bangsa Tatar di kota meninggalkan kota. Akkirman diserahkan kepada Rusia bersama Besarabia dengan Perjanjian Bükreş 1812.", "1e7e3f9e"]},
"OLAYLAR_P0056:1806-12-25:0":{"b": ["Miloradovich memasuki Bükreş — pendudukan Rusia atas Eflak", "62e4a8e1"], "d": ["Ketika tentara Rusia memasuki Boğdan, Mustafa Paşa, komandan Rusçuk, mengirim pasukan ke Bükreş dan pasukan itu menguasai kota. Detasemen Jenderal Miloradovich mengeluarkan mereka dari kota; pasukan Utsmani mundur ke Yergöğü. Bükreş sejak tanggal ini tetap di bawah pendudukan Rusia hingga Perjanjian Bükreş 1812.", "217aa20b"]},
"OLAYLAR_P0056:1810-06-10:0":{"b": ["Penyerahan Silistre kepada Rusia", "d687d04b"], "d": ["Silistre, yang bertumpu pada pengepungan Bagration pada musim gugur 1809, dikepung kembali dalam ekspedisi 1810 atas perintah panglima Kamenski. Pekerjaan pengepungan yang dimulai pada akhir Mei berlangsung beberapa hari dan benteng menyerah dengan syarat garnisun keluar dengan bebas. Pada hari-hari yang sama Pazarcık direbut dengan serbuan dan Hezargrad jatuh. Rusia menahan Silistre setahun; pada musim semi 1811 Kutuzov meledakkan tembok dan meninggalkan benteng.", "56cdb224"]},
"OLAYLAR_P0056:1810-10-01:0":{"b": ["Penyerahan Niğbolu dan Kule (Turnu) kepada Rusia tanpa perlawanan", "e297a862"], "d": ["Setelah Rusçuk dan Yergöğü menyerah, panglima Kamenski berbaris ke barat menyusuri sungai untuk merebut benteng-benteng Tuna hingga perbatasan Serbia. Niğbolu dan Kule di tepi seberang menyerah tanpa perlawanan; detasemen Rusia merebut Plevne, Lofça, dan Selvi serta meruntuhkan benteng-bentengnya. Rusia menahan Niğbolu enam bulan dan meninggalkannya dengan meledakkan benteng pada April 1811.", "f77715d7"]},
"OLAYLAR_P0056:1811-07-04:0":{"b": ["Pertempuran Rusçuk dan mundurnya Kutuzov ke tepi kiri Tuna setelah meruntuhkan Rusçuk", "6af4bf85"], "d": ["Perdana menteri yang berangkat dari Şumnu pada awal Juni menyerang tentara Rusia di depan Rusçuk, kalah, dan mundur ke posisi berbentengnya di selatan. Meskipun menang dalam pertempuran ini, Kutuzov menganggap tetap tinggal di Rusçuk berbahaya; ia meruntuhkan benteng pertahanan kota dan memindahkan seluruh pasukannya ke tepi kiri Tuna. Perdana menteri merebut kembali Rusçuk yang dikosongkan. Dengan demikian cengkeraman Rusia di kota yang diterima Kaminski pada 26 September 1810 setelah pengepungan berdarah berlangsung sembilan bulan. Menurut catatan TDV, sebelum pergi Kutuzov memerintahkan peledakan benteng pertahanan di sekitar kota dan benteng abad pertengahan; dalam kebakaran yang timbul, dua belas dari tiga puluh delapan masjid jami yang ada di kota pada 1810 dan dua dari delapan mescid hancur seluruhnya. Pada musim gugur tahun yang sama, melintasnya tentara Utsmani di Tuna akan berujung pada pengepungan Slobozia.", "3b247b6b"]},
"OLAYLAR_P0056:1828-05-07:0":{"b": ["Korps Infanteri ke-6 Rusia melintasi Prut dan memasuki Memleketeyn (Perang Utsmani-Rusia 1828-1829)", "9d9aaaad"], "d": ["Setelah deklarasi perang Rusia, tentara Marsekal Wittgenstein memulai operasi. Korps Infanteri ke-6 melintasi Prut dan memasuki Boğdan serta Eflak; pelopornya di bawah komando Jenderal Geismar mengarah ke Eflak Kecil. Beberapa hari kemudian Korps ke-7 mengepung İbrail; Korps ke-3 bersiap melintasi Tuna antara İsmail dan Reni. Memleketeyn akan tetap di bawah pendudukan Rusia hingga 1834.", "cba5d549"]},
"OLAYLAR_P0056:1829-06-30:0":{"b": ["Penyerahan Silistre kepada Diebitsch — pendudukan Rusia yang akan berlangsung hingga 1836", "55e28ab1"], "d": ["Pada awal ekspedisi 1829, panglima Rusia yang baru, Diebitsch, memilih Silistre sebagai sasaran pertama. Garnisun melawan dengan gigih pekerjaan pengepungan yang dipimpin Jenderal Schilder; Diebitsch meninggalkan sebagian pasukannya di pengepungan dan berbaris ke belakang perdana menteri. Pengepungan berlanjut dan benteng menyerah. Rusia menahan Silistre hingga 1836 bahkan setelah perang usai.", "4c1a9e8e"]},
"OLAYLAR_P0056:1836-01-01:0":{"b": ["Rusia mengosongkan Silistre", "4fe2afaf"], "d": ["Setelah Perjanjian Edirne 1829, Rusia tidak mengosongkan Silistre dan menahan benteng hingga 1836. Setelah tentara Rusia mundur, gubernur Selim Paşa membangun sebuah masjid besar berkubah tunggal di tengah kota yang setengah hancur.", "39444f60"]},
"OLAYLAR_P0056:1853-07-03:0":{"b": ["Tentara Rusia melintasi Prut dan mulai menduduki Memleketeyn (Eflak-Boğdan) — jalan menuju Perang Krimea", "77862041"], "d": ["Ketika tuntutan Menshikov dalam sengketa tempat-tempat suci di Yerusalem ditolak oleh Bâbıâli, Tsar I. Nikolai memerintahkan pendudukan beylik-beylik Tuna yang tunduk pada Utsmani 'sebagai jaminan hingga Turki memenuhi tuntutan kami yang sah'. Pelopor tentara di bawah komando Pangeran Gorchakov melintasi Prut dan dua belas hari kemudian memasuki Bükreş; setelahnya pasukan utama menyebar ke beylik dalam tiga kolom. Pendudukan yang dilakukan tanpa deklarasi perang ini menyebabkan krisis diplomatik di Eropa dan pada Oktober 1853 deklarasi perang Utsmani; Rusia baru mengosongkan beylik pada musim panas 1854 di bawah tekanan Austria.", "04443242"]},
"OLAYLAR_P0057:1442-01-16:0":{"b": ["Müşa'şa'î menetap di Havîza — pemerintahan Müşa'şa' dimulai di Huzistan", "674d0173"], "d": ["Muhammed b. Felâh, yang muncul dengan klaim Mehdî, setelah bertahan di antara suku-suku Meâdî, berhasil menetap di Havîza yang berada di bawah kendali Timurid pada tahun berikutnya. Kota itu menjadi pusat dinasti Müşa'şa'î yang akan berkuasa di Huzistan.", "53937c8f"]},
"OLAYLAR_P0057:1508-05-02:0":{"b": ["Şah İsmâil menghubungkan Havîza — Müşa'şa'î menjadi gubernur bawahan Safawi", "7e245f4d"], "d": ["Şah İsmâil membunuh sebagian anggota dinasti Müşa'şa' yang dituduhnya zindik dan menghubungkan kawasan Havîza dengan administrasinya sendiri. Para pemimpin Müşa'şa' sesudahnya melanjutkan keberadaan mereka sebagai gubernur bawahan Safawi.", "ee776160"]},
"OLAYLAR_P0057:1534-01-01:0":{"b": ["Benteng Pasin, Şüregel, dan Oltu direbut dari Safawi — antara Erzurum dan Kars", "68f297aa"], "d": ["Selama Ekspedisi Irakeyn Kanûnî Sultan Süleyman, benteng-benteng Pasin, Şüregel, dan Oltu antara Erzurum dan Kars direbut dari Safawi.", "06909003"]},
"OLAYLAR_P0057:1557-04-02:0":{"b": ["Özdemir Paşa merebut pelabuhan Masavva'", "4cc1d4ad"], "d": ["Özdemir Paşa, beylerbeyi Eyalet Habeş, setelah merebut kepulauan Dehlek, merebut kota Masavva' di pesisir seberang pada 2 April 1557; setelah itu Arkîko juga masuk ke administrasi Utsmani. Dengan demikian pelabuhan utama Habasyah yang terbuka ke Laut Merah jatuh ke tangan Utsmani.", "7c5e89f0"]},
"OLAYLAR_P0057:1793-01-31:0":{"b": ["Bergabungnya County Nice ke Prancis", "a140cab2"], "d": ["Setelah bergabungnya Savoy pada November 1792, Konvensi Nasional Prancis mengesahkan bergabungnya County Nice milik Kerajaan Sardinia ke Prancis pada 31 Januari 1793; kawasan itu menjadi departemen Alpes-Maritimes. Nice dikembalikan kepada Sardinia dengan Perjanjian Paris I tertanggal 30 Mei 1814 setelah kekalahan Napoleon.", "b313c90b"]},
"OLAYLAR_P0057:1917-01-09:0":{"b": ["Pertempuran Refah — kavaleri Inggris-Anzac merebut posisi Mağrunteyn dan Refah", "5053c8ef"], "d": ["Divisi Berkuda Anzac Pasukan Ekspedisi Mesir yang melintasi Sînâ, brigade Korps Unta Imperial, dan brigade yeomanry Inggris menyerang posisi Utsmani yang diduduki dengan tabya di Mağrunteyn, sekitar satu kilometer di selatan Refah. Setelah pertempuran sengit, terobosan bangsa Selandia Baru dan pasukan unta meruntuhkan pertahanan Utsmani; posisi itu dan Refah di dekatnya direbut dan pasukan Inggris mencapai perbatasan Palestina.", "7f90289f"]},
"OLAYLAR_P0057:1918-03-12:0":{"b": ["Operasi musim dingin Kâzım Karabekir: Hasankale (Pasinler) direbut kembali bersama Erzurum", "27df4879"], "d": ["Pasukan Utsmani di bawah Kâzım Karabekir Paşa, yang memulai operasi di timur setelah runtuhnya tentara Rusia, merebut kembali Erzincan, Erzurum, dan Hasankale di timur Erzurum meskipun kondisi musim dingin yang berat; kemajuan mencapai Kars pada 25 April 1918.", "80a72c73"]},
"OLAYLAR_P0057:1919-01-23:0":{"b": ["Pendudukan Eskişehir oleh Inggris", "8e349037"], "d": ["Setelah Gencatan Senjata Mondros, negara-negara Entente mulai menguasai simpul-simpul kereta api Anatolia. Menurut artikel Eskişehir TDV, kota diduduki Inggris pada 23 Januari 1919. Pasukan Inggris mengosongkan Eskişehir pada 20 Maret 1920.", "5bb8774d"]},
"OLAYLAR_P0057:1919-05-11:0":{"b": ["Pendaratan Italia di pesisir Anatolia Barat Daya — Marmaris, Bodrum, Kuşadası", "15d6fb7a"], "d": ["Italia, yang menarik diri dari Konferensi Perdamaian Paris untuk memprotes sikap sekutunya yang pro-Yunani, mendaratkan pasukan di pesisir barat daya setelah Antalya. Menurut TDV, Marmaris mengalami pendudukan Italia pada 5 Mei, Bodrum pada 11 Mei, dan Kuşadası pada 13 Mei. Pada hari-hari yang sama bangsa Yunani juga mendarat di Fethiye; persaingan kedua negara atas Anatolia Barat menyiapkan jalan menuju pendudukan İzmir.", "82266143"]},
"OLAYLAR_P0057:1919-05-26:0":{"b": ["Pasukan Yunani memasuki Manisa dan Aydın", "a4230775"], "d": ["Tentara Yunani yang mendarat di İzmir pada 15 Mei dalam waktu singkat menyebar ke pedalaman. Menurut artikel Manisa TDV, pasukan Yunani memasuki kota pada 26 Mei 1919; menurut artikel Aydın, Aydın diduduki keesokan harinya, 27 Mei. Pendudukan Manisa akan berlangsung hingga September 1922.", "514ead8b"]},
"OLAYLAR_P0057:1919-06-28:0":{"b": ["Pendudukan Burdur oleh Italia — mundurnya kompi yang mengarah ke Isparta", "874e9d6d"], "d": ["Italia, yang menduduki Antalya, maju ke wilayah pedalaman. Menurut artikel Isparta TDV, pasukan Italia menduduki Burdur pada 28 Juni dan pada 15 Agustus mengarah ke Isparta dengan satu kompi tentara. Ketika rakyat Isparta menolak tawaran penyerahan senjata dan menyatakan akan melawan, Italia mundur keesokan harinya.", "35806188"]},
"OLAYLAR_P0057:1919-06-30:0":{"b": ["Pembebasan singkat Aydın dan pendudukan ulang pada 4 Juli", "753c739f"], "d": ["Pasukan nasional diorganisasi di sekitar Ödemiş, Nazilli, dan Aydın melawan pendudukan Yunani. Menurut artikel Aydın TDV, kota yang diduduki pada 27 Mei 1919 dibebaskan untuk waktu singkat pada 30 Juni, tetapi pada 4 Juli kembali mengalami pendudukan Yunani. Kota itu sesudahnya tetap di bawah pendudukan hingga 7 September 1922.", "a0031b01"]},
"OLAYLAR_P0057:1919-07-23:0":{"b": ["Pendudukan Muğla oleh Italia", "a4f5a926"], "d": ["Italia memperluas pendudukannya di pesisir barat daya ke wilayah pedalaman. Menurut artikel Muğla TDV, kota mengalami pendudukan Italia pada 23 Juli 1919. Pendudukan Muğla berlangsung hingga 5 Juli 1921.", "b77c243c"]},
"OLAYLAR_P0057:1919-10-15:0":{"b": ["Dimulainya administrasi militer Prancis di Trakia Barat", "5801e6de"], "d": ["Trakia Barat, yang berada di tangan Bulgaria yang kalah dalam Perang Dunia Pertama, ditempatkan di bawah kendali negara-negara Entente selama perundingan perdamaian berlangsung. Menurut artikel Trakia Barat TDV, kawasan itu diduduki pasukan Prancis pada 15 Oktober 1919; Müdâfaa-i Hukuk Cemiyeti Trakia Barat memindahkan pusatnya ke Gümülcine pada masa ini. Administrasi Prancis berlangsung hingga kawasan itu diserahkan kepada Yunani pada Mei 1920 dengan keputusan San Remo.", "58f44e3a"]},
"OLAYLAR_P0057:1920-03-20:0":{"b": ["Inggris mengosongkan Eskişehir", "6820e164"], "d": ["Eskişehir, yang berada di bawah pendudukan Inggris sejak Januari 1919, dikosongkan oleh Inggris pada 20 Maret 1920 menurut artikel Eskişehir TDV. Beberapa bulan kemudian, pada Juni 1920, kota menjadi pusat Front Barat yang dibentuk TBMM.", "5f817d34"]},
"OLAYLAR_P0057:1920-06-22:0":{"b": ["Serangan musim panas Yunani — pendudukan Akhisar, Soma, Balıkesir, dan Alaşehir", "f096d2b4"], "d": ["Dengan sekutu memberi izin kepada tentara Yunani untuk maju melewati garis Milne, serangan besar Yunani dimulai di Anatolia Barat. Menurut artikel Millî Mücadele TDV, pasukan Yunani yang bergerak dalam tiga kolom pada 22 Juni merebut Akhisar, Kırkağaç, Soma, dan Balıkesir. Di selatan, Alaşehir diduduki pada 26 Juni dan Nazilli pada 3 Juli.", "bb4b4b94"]},
"OLAYLAR_P0057:1920-07-08:0":{"b": ["Pendudukan Bursa oleh Yunani", "7c2b32a1"], "d": ["Kolom utara serangan musim panas mengarah ke Marmara setelah Balıkesir. Menurut artikel Bursa dan Millî Mücadele TDV, Bursa mengalami pendudukan Yunani pada 8 Juli 1920. Penghinaan terhadap makam-makam para penguasa Utsmani pertama menimbulkan reaksi besar di seluruh negeri.", "2f040dcd"]},
"OLAYLAR_P0057:1920-07-20:0":{"b": ["Pendudukan Trakia Timur oleh tentara Yunani — Edirne dan Kırklareli", "9eb3bda1"], "d": ["Yunani, sebelum Perjanjian Sevr ditandatangani, mulai merebut Trakia Timur secara nyata juga. Menurut artikel Millî Mücadele TDV, tentara Yunani merebut seluruh Trakia pada 20 Juli; perkembangan ini mendorong padişah di İstanbul untuk memanggil Dewan Kesultanan dua hari kemudian. Kırklareli mengalami pendudukan pada 26 Juli, dan Edirne juga masuk ke administrasi Yunani pada bulan yang sama.", "4c68dd1f"]},
"OLAYLAR_P0057:1920-07-28:0":{"b": ["Tentara Merah memasuki Nahçıvan", "6dcb9005"], "d": ["Inggris, yang memasuki kawasan itu pada awal 1919, membubarkan Republik Aras dan meninggalkan Nahçıvan pada musim panas tahun yang sama. Menurut artikel Nahçıvan TDV, Tentara Merah memasuki Nahçıvan pada 28 Juli 1920 dan menyerahkan administrasi kepada kaum komunis, dan Republik Sosialis Soviet Nahçıvan didirikan. Status kawasan itu ditetapkan pada 1921 dengan perjanjian yang ditandatangani di Kars sebagai satuan otonom yang bergantung pada Azerbaijan.", "bc49ebba"]},
"OLAYLAR_P0057:1920-08-29:0":{"b": ["Pendudukan Uşak oleh Yunani", "74ad2713"], "d": ["Tentara Yunani melanjutkan kemajuannya untuk memaksakan Perjanjian Sevr, yang tidak diakui Ankara. Menurut artikel Uşak dan Millî Mücadele TDV, setelah Gediz, Uşak juga diduduki pada 29 Agustus 1920. Mustafa Kemal Paşa telah memeriksa pasukan Kuvâ-yi Milliye di kota itu sekitar sebulan sebelum pendudukan ini.", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["Pendudukan İnegöl dan Yenişehir oleh Yunani", "4a0460e7"], "d": ["Pasukan Yunani di Bursa mulai maju ke timur, ke arah Eskişehir. Menurut artikel Millî Mücadele TDV, İnegöl dan Yenişehir direbut pada 25 Oktober 1920. Ketika dipahami bahwa kemajuan Yunani tidak dapat dihentikan dengan pasukan milisi, front barat diorganisasi ulang berdasarkan tentara reguler.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Berakhirnya pendudukan Italia atas Burdur (tahun)", "609123c8"], "d": ["Burdur, yang diduduki Italia pada 28 Juni 1919, mengalami pendudukan Italia singkat antara 1919-1921 menurut artikel Burdur TDV. Sumber tidak memberikan hari pengosongan; di peta pendudukan berakhir pada awal tahun 1921. Italia sepenuhnya mundur dari zona pendudukannya di Anatolia pada musim panas 1921.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["Serangan kedua tentara Yunani — pendudukan Bilecik, Afyon, dan Adapazarı", "9ae146e2"], "d": ["Tentara Yunani, yang mendaratkan pasukan baru di İzmir setelah kekalahan İnönü Pertama, kembali melancarkan serangan sebelum tenggat yang diakui Konferensi London habis. Menurut artikel Millî Mücadele TDV, bangsa Yunani menduduki Bilecik dan Afyon pada 23 Maret. Di utara Adapazarı juga mengalami pendudukan Yunani pada 25 Maret.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Pasukan Turki mengosongkan Batum", "ba5745dc"], "d": ["Ketika Inggris mundur dari Kaukasus pada Juli 1920, mereka mengosongkan Batum dan kota itu diambil alih pemerintah Georgia. Menurut artikel Batum TDV, Perjanjian Moskow yang ditandatangani dengan Rusia Soviet pada 16 Maret 1921 menyerahkan Batum kepada Georgia. Pasukan Turki mengosongkan kota pada 28 Maret 1921 dan Batum menjadi pusat Republik Otonom Acara yang didirikan di dalam Georgia.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["Perebutan kembali Afyon — pertempuran Aslıhanlar", "2bbba17b"], "d": ["Setelah serangan Yunani dihentikan di İnönü Kedua pada 1 April, Afyon direbut kembali di front selatan pada 7 April. Artikel Millî Mücadele TDV meringkasnya dengan 'dikalahkan telak di Aslıhanlar dan Afyon direbut kembali pada 7 April'; namun kajian sejarah militer menempatkan pertempuran Aslıhanlar-Dumlupınar setelah pengosongan Afyon, antara 8-15 April, dan menulis bahwa keunggulan taktis tetap di pihak Yunani — kedua penuturan tidak cocok, keduanya diberikan. Kemenangan İnönü dirayakan dengan rapat umum di seluruh negeri, terutama di İstanbul.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["Pembebasan İzmit — setelah Adapazarı", "cec60e36"], "d": ["Adapazarı, yang mengalami pendudukan Yunani pada Maret 1921, direbut kembali pada 21 Juni menurut artikel Adapazarı TDV. Menurut artikel İzmit TDV, İzmit, yang diduduki pertama oleh Inggris kemudian oleh Yunani pada 6 Juli 1920, dibebaskan pada 28 Juni 1921. Bangsa Yunani membakar bagian pasar ketika meninggalkan kota.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["Pembebasan Muğla dari pendudukan Italia", "143ddf98"], "d": ["Italia mulai mundur dari zona pendudukannya di Anatolia pada musim panas 1921; pengosongan Antalya telah dimulai pada 1 Juni. Menurut artikel Muğla TDV, Muğla, yang berada di bawah pendudukan Italia sejak 23 Juli 1919, dibebaskan pada 5 Juli 1921.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["Pengosongan Eskişehir — tentara Yunani memasuki Eskişehir, Kütahya, dan Bilecik", "a948a74d"], "d": ["Tentara Turki, yang tertangkap tanpa persiapan dalam pertempuran Kütahya-Eskişehir, mundur ke timur Sakarya atas perintah Mustafa Kemal Paşa. Menurut artikel-artikel TDV, bangsa Yunani memasuki Eskişehir pada 20 Juli 1921, Kütahya pada 21 Juli, dan Bilecik pada 22 Juli. Raja Yunani Konstantinos memimpin dewan perang di Kütahya pada 28 Juli dan tentara bersiap menyerang ke arah Ankara.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Penarikan pasukan Italia dari Marmaris dan Kuşadası", "1d672994"], "d": ["Italia, yang berada di pesisir Anatolia barat daya sejak Mei 1919, mengosongkan zona pendudukan selangkah demi selangkah setelah mendekat kepada Pemerintah Ankara. Antalya dan Bodrum telah dikosongkan pada musim panas 1921; pasukan Italia terakhir juga meninggalkan Kuşadası dan Marmaris pada akhir April 1922.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Serangan Besar dimulai", "efba4bd3"], "d": ["Setelah persiapan setahun sejak Sakarya, tentara Turki melancarkan serangan umum di front Afyon. Menurut artikel Millî Mücadele dan Kütahya TDV, Serangan Besar dimulai dari Afyon pada pagi 26 Agustus 1922 dan perlawanan tentara Yunani patah dalam waktu singkat.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["Pembebasan Afyon", "beaeef23"], "d": ["Pada hari kedua serangan, front Yunani ditembus di depan Afyon. Menurut artikel Afyonkarahisar TDV, pada akhir Serangan Besar yang dipimpin langsung oleh Atatürk, pasukan Yunani dihancurkan dan kota dibebaskan pada 27 Agustus 1922. Hari ini dirayakan sebagai hari pembebasan Afyon.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["Pertempuran Lapangan Panglima Tertinggi — pembebasan Kütahya", "376d3118"], "d": ["Pasukan utama tentara Yunani terkepung antara Afyon dan Dumlupınar. Menurut artikel Millî Mücadele TDV, operasi pengepungan diselesaikan pada 30 Agustus dengan Pertempuran Panglima Tertinggi yang dipimpin langsung oleh Panglima Tertinggi Mustafa Kemal Paşa. Menurut artikel Kütahya TDV, pada hari yang sama sebuah divisi kavaleri membebaskan Kütahya yang dibakar dan dihancurkan pasukan Yunani yang mundur.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["Pembebasan Uşak", "0f2d44d1"], "d": ["Setelah Pertempuran Panglima Tertinggi, sisa-sisa tentara Yunani mundur ke barat, ke arah İzmir. Menurut artikel Uşak TDV, Uşak, yang berada di bawah pendudukan sejak 29 Agustus 1920, dibebaskan pada 1 September 1922 dengan masuknya pasukan nasional ke kota. Dalam kebakaran yang ditimbulkan pasukan pendudukan yang mundur, sekitar tiga perempat kota terbakar.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["Pembebasan Eskişehir", "f442de5c"], "d": ["Di sayap utara Serangan Besar, pasukan Yunani terpaksa meninggalkan Eskişehir juga. Menurut artikel Eskişehir TDV, kota yang berada di bawah pendudukan sejak 20 Juli 1921 dibebaskan pada 2 September 1922 setelah kemenangan 30 Agustus. Pada akhir pendudukan tiga belas bulan, bagian pasar telah dibakar dan kota setengah hancur.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["Pembebasan Bilecik", "35dbd49b"], "d": ["Menurut artikel Bilecik TDV, kota mengalami pendudukan Yunani tiga kali selama Perjuangan Nasional; pendudukan ketiga yang dimulai pada 22 Juli 1921 berakhir pada 6 September 1922. Dalam kebakaran yang ditimbulkan pasukan Yunani ketika mengosongkan kota, sebagian besar rumah, toko, dan gedung pemerintahan terbakar.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["Pembebasan Aydın", "ef1280b5"], "d": ["Dengan mendekatnya tentara Turki ke İzmir, pasukan Yunani di lembah Menderes juga mundur. Menurut artikel Aydın TDV, kota dibebaskan oleh pasukan Turki pada 7 September 1922 dalam keadaan sebagian hancur dan penduduknya sangat berkurang. Bangsa Yunani yang mundur telah membakar sebagian besar kota.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["Perebutan kembali Bursa", "6ad1da0b"], "d": ["Setelah pembebasan İzmir, tentara Turki maju ke utara menuju pesisir Marmara. Menurut artikel Bursa TDV, kota yang berada di bawah pendudukan Yunani sejak 8 Juli 1920 direbut kembali pada 10-11 September 1922. Berbarisnya tentara dari sini ke Çanakkale membuat Inggris cemas dan membuka jalan bagi perundingan Mudanya.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["Penyerahan Trakia Timur — Kırklareli dan Tekirdağ", "2a08d65c"], "d": ["Gencatan Senjata Mudanya mengatur pengosongan Trakia Timur oleh tentara Yunani dan penyerahannya kepada Turki; Refet Paşa, yang ditugaskan menerima Trakia, tiba di İstanbul pada 19 Oktober. Menurut TDV, Kırklareli yang berada di bawah pendudukan sejak 26 Juli 1920 direbut kembali pada 10 November 1922, dan Tekirdağ dikembalikan kepada Turki sesuai gencatan senjata pada 13 November. Dengan demikian Trakia Timur bergabung ke wilayah Turki tanpa pertempuran.", "cb085872"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Eretna menghubungkan kawasan Tokat, Kayseri, dan Samsun dengan dirinya", "4a088f9f"], "d": ["Emîr Eretna, yang menguat di Anatolia sebagai gubernur Ilkhanid, setelah memperoleh kembali dukungan Sultan Mamluk en-Nâsır Muhammed memperluas batasnya pada 1339 dan menghubungkan kawasan Tokat, Kayseri, dan Samsun dengan dirinya. Kawasan Zamantı di timur Kayseri juga masuk ke administrasi Eretna pada masa ini. Beylik menyatakan kemerdekaannya pada 1341 dengan wafatnya en-Nâsır.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Halil Bey dari Dulkadirli memperluas batasnya hingga Zamantı", "aa911e87"], "d": ["Dengan naiknya Mehmed Bey yang masih kecil ke kepala Beylik Eretna, serbuan Türkmen dari selatan meningkat ke tanah Eretna yang melemah. Pada 1360, ketika Ömer Bey, salah satu pemimpin Türkmen, merebut Malatya, Halil Bey dari Dulkadiroğlu juga memperluas batas beyliknya hingga Zamantı di timur Kayseri. Dengan demikian kawasan Zamantı antara Elbistan dan Kayseri jatuh ke tangan Dulkadiroğulları dan beylik menguasai kawasan itu hingga aneksasi Utsmani tahun 1515.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Yıldırım Bayezid kembali mengepung İstanbul dengan ketat", "244834ca"], "d": ["İstanbul, yang diblokade secara berkala sejak 1391, kembali dikepung ketat oleh Yıldırım Bayezid pada musim semi 1394. Hubungan dengan Bizantium, yang sejak 1371 membayar upeti kepada Utsmani dan mengirim bantuan militer, dengan demikian berubah menjadi permusuhan terbuka. Pengepungan dicabut dengan munculnya bahaya Timur dan Pertempuran Ankara 1402.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Perdamaian Bizantium dengan II. Murad — Bizantium kembali setuju membayar upeti", "6474d704"], "d": ["II. Murad, yang mengepung İstanbul pada 1422 terhadap Bizantium yang mendukung Düzmece Mustafa, menandatangani perjanjian damai dengan kaisar Bizantium pada 22 Februari 1424. Dengan perjanjian ini Bizantium kembali setuju membayar upeti kepada Utsmani dan setuju mengembalikan tempat-tempat yang diambilnya setelah 1402 di pesisir Marmara, Aegea, dan Laut Hitam, kecuali benteng Silivri dan Terkos; upeti tahunan yang dihindarinya dengan perjanjian bersama Emîr Süleyman pada 1403 dengan demikian kembali. Bizantium mempertahankan keadaan ini hingga penaklukan İstanbul pada 1453.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Benteng Bayburt dan Kiğı diterima dari Safawi — Erzincan dan Bayburt diberikan kepada Bıyıklı Mehmed Bey", "2c7fd65e"], "d": ["Ketika Yavuz Sultan Selim, yang kembali dari Tebriz setelah kemenangan Çaldıran, berada di perkemahan, tiba kabar bahwa benteng Bayburt dan Kiğı telah diterima. Sancak beyi Trabzon Bıyıklı Mehmed Bey dan sancak beyi Yanya Mustafa Bey merebut Bayburt, yang dipertahankan Kara Maksûd-i Sultânî, salah satu emîr Şah İsmâil, pada Oktober 1514. Erzincan, yang masuk ke kekuasaan Utsmani tanpa perang, diberikan kepada Bıyıklı Mehmed Bey bersama Bayburt sebagai beylerbeyilik pada 23 Oktober 1514, dan Bayburt dijadikan pusat sancak.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Yavuz Sultan Selim kembali dari ekspedisi Tebriz ke Amasya dan melewatkan musim dingin di sana", "49d51f94"], "d": ["Yavuz Sultan Selim, yang tinggal sembilan hari di Tebriz, mengurungkan niat melewatkan musim dingin di Iran karena kesulitan perbekalan dan keengganan tentara, dan kembali lewat Kars dan Bayburt. Padişah, yang merayakan Hari Raya Ramadan di Niksar, tiba di Amasya dan melewatkan musim dingin di sini. Ia bermaksud kembali berbaris melawan Safawi pada tahun berikutnya; di Amasya tekanan para yeniçeri untuk kembali ke İstanbul dimulai, dan ekspedisi berlanjut pada musim semi 1515 dengan penaklukan Kemah.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Eflak, Boğdan, dan Transilvania bersama-sama memberontak melawan Utsmani", "e71d3ee9"], "d": ["Pada pertengahan 1594 tiga voyvodalık di utara Tuna — Eflak, Boğdan, dan Transilvania — memutuskan bertindak bersama melawan Utsmani. Voyvoda Boğdan Aron Tiran bergabung dengan Liga Suci yang dibentuk Kaisar Austria dan Paus VIII. Clemens dan menempatkan dirinya di bawah Kepangeranan Transilvania; voyvoda Eflak Mihai Viteazul bergabung dalam gerakan karena ketidakpuasan terhadap beban pajak yang berat. Pada 13 November 1594 pemberontakan serentak melawan administrasi Utsmani dimulai di Eflak dan Boğdan, dan dengan dukungan Transilvania gerakan meluas ke selatan Tuna, ke wilayah Utsmani. Menurut TDV İslâm Ansiklopedisi, aliansi tiga pihak ini membuka front utara Perang Panjang Utsmani-Habsburg (1593-1606) yang berlangsung pada tahun-tahun yang sama.", "30f44add"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Penaklukan Benteng Ostrovica di lembah Una", "5c6cc91b"], "d": ["Ostrovica, yang berada di tangan keluarga Frankapan dan bangsawan Kroasia lainnya, berdiri di atas punggung bukit curam yang menghubungkan bagian utara dan selatan lembah Una. Pada 1523 ia masuk ke administrasi Utsmani dan menampung garnisun Utsmani hingga 1878. Benteng ini memperoleh arti pentingnya terutama setelah Karlofça (1699): karena dekat dengan perbatasan Venesia dan Austria, ia diperluas dan menjadi pusat kapetanat Stara Ostrovica; kota kecil Kulen Vakuf didirikan di kakinya pada awal abad XVIII.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Penaklukan benteng Udbina dan Krbava — Lika masuk ke administrasi Utsmani", "5fe329d3"], "d": ["Dataran Krbava telah kosong pada 1524 dan di Udbina hanya tersisa garnisun Karlović. Karlović meraih kemenangan terakhir di depan benteng pada April 1527, tetapi pada akhir Mei Udbina jatuh ke tangan pasha Bosnia bersama benteng Mrsinj dan Komić. Pada tahun yang sama wilayah Gospić diberikan kepada para ağa Senković. Setelah itu Lika dan Krbava menjadi bagian sancak yang berpusat di Obrovac, yang pada 1580 bernama Kırka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Peralihan pasti Drežnik dan županija Drežnik ke administrasi Utsmani", "6624ad14"], "d": ["Drežnik, yang berada di tangan Frankapan sejak 1323, sempat dikuasai Utsmani secara sementara pada 1578. Pada 1592 benteng dan seluruh županija Drežnik masuk ke administrasi Utsmani secara pasti; pada tahun yang sama Bihaç juga jatuh. Pada abad XVIII Drežnik bergantung pada kapetanat Ostrožac.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Perebutan Benteng Cetin oleh Utsmani", "98815f97"], "d": ["Cetin, benteng kunci pertahanan kawasan Slunj terhadap Utsmani sejak pertengahan abad XVI, masuk ke administrasi Utsmani pada 1636 setelah dikepung berkali-kali. Masa Utsmani pertama ini berlangsung dua tahun.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Benteng Cetin kembali ke pihak Habsburg", "690f9f84"], "d": ["Cetin, yang jatuh ke tangan Utsmani pada 1636, kembali ke pertahanan perbatasan Kroasia-Habsburg pada 1638 dan tetap demikian hingga 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin kembali menjadi benteng Utsmani", "e1750675"], "d": ["Cetin kembali menjadi benteng Utsmani pada 1670 dan dibentengi secara menyeluruh pada abad XVIII: benteng abad pertengahan dikelilingi tembok berbenteng bundar. Benteng ini menguasai ujung barat laut perbatasan Bosnia hingga 1790.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Hilangnya Lika dan Krbava — Udbina dan Gospić jatuh ke tangan pasukan perbatasan Habsburg", "01277a38"], "d": ["Dalam perang yang berlanjut setelah kekalahan di Wina, pasukan perbatasan Kroasia di bawah jenderal Karlovac, Herberstein, merebut Udbina pada 1689; Gospić juga lepas dari administrasi Utsmani pada tahun yang sama. Lika Utsmani yang berlangsung lebih dari 160 tahun berakhir, tempat-tempat yang kosong dihuni penduduk Kroasia baru, dan Udbina menjadi benteng penting pertahanan perbatasan terhadap Utsmani hingga Perdamaian Ziştovi (1791).", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Perebutan Drežnik oleh Austria — front barat Pertempuran Dubica", "05d5e5f1"], "d": ["Dalam perang Utsmani-Austria 1788-1791, pasukan Habsburg merebut Drežnik di sebelah barat Bihaç. Berdasarkan pasal 4 Perjanjian Ziştovi, Drežnik dan Cetin tetap di bawah administrasi Habsburg dan tidak pernah kembali ke Bosnia.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Perebutan Benteng Cetin oleh Austria", "df182480"], "d": ["Pada 1790 tentara Habsburg menyerang Cetin, Bužim, dan Velika Kladuša, dan merebut Cetin. Mobilisasi dan serangan balik yang diumumkan gubernur Bosnia tidak mampu merebut kembali benteng; pasal 4 Perjanjian Ziştovi menyerahkan Cetin kepada Habsburg. Para serhadli Bosnia merebut kembali benteng itu dalam serbuan singkat pada 1809 dan 1813.", "fc69baec"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik pertama kali disebut — perbatasan dengan Bizantium dimulai di Bilecik", "7b69f743"], "d": ["Dalam peristiwa tahun 683 yang dikutip Neşrî, Bilecik disebut sebagai tempat dimulainya perbatasan antara beylik uç Osman Bey dan Bizantium. Ini adalah penyebutan pertama yang diketahui dalam sejarah atas permukiman itu; bukan pendiriannya.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Koin atas nama Gāzân Han di Burdur — saksi pertama kota yang diketahui", "01974ddc"], "d": ["Hamîdoğulları, di bawah tekanan Ilkhanid, terpaksa mencetak koin atas nama Gāzân Han di Burdur pada tahun 699. Koin ini adalah saksi tertulis/bertanggal pertama Burdur.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorum disebut dalam negeri Eretna — saksi pertama kota yang diketahui", "bf7bd67f"], "d": ["Çorum dihitung di antara kota-kota di bawah kekuasaan Eretna Bey ketika ia wafat pada Muharram 753. Pendirian kota tidak diketahui; penyebutan ini adalah saksi bertanggal paling awal yang dapat ditemukan.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["İbrail pertama kali disebut — dokumen imtiyaz Vlaicu Vodă untuk para pedagang Braşov", "0b3517a7"], "d": ["Voyvoda Eflak Vladislav memberikan dokumen kepada para pedagang Braşov yang memberikan kemudahan saat mengangkut barang melalui jalan İbrail. Dokumen ini adalah saksi tertulis pertama İbrail yang diketahui; tempat itu di sini belum disebut sebagai kota, melainkan sebagai ujung jalan di Tuna. Bukan tanggal pendirian.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Kişinev pertama kali disebut dalam ferman voyvoda Boğdan", "a50799d7"], "d": ["Nama Kişinev pertama kali muncul dalam sebuah ferman tahun 1420 dari voyvoda Boğdan Aleksandru. Kota lama tetap sebagai kota kecil Boğdan; ketika beralih ke Rusia bersama Besarabia pada 1812, ia menjadi pusat provinsi.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Kalas pertama kali disebut dalam dokumen voyvoda Boğdan", "a31af8a2"], "d": ["Voyvoda Boğdan II. Ştefan membebaskan dua gerobak Biara Humor yang mengangkut ikan dari Kalas dari bea cukai. Dokumen ini adalah saksi tertulis pertama Kalas yang diketahui dengan pasti; permukiman mungkin sebelumnya sudah ada sebagai desa nelayan di tepi Tuna.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Nama Mostar pertama kali muncul dalam dokumen Dubrovnik", "a599bc55"], "d": ["Nama Mostar pertama kali muncul dalam dokumen Dubrovnik bertanggal 3 April 1452; permukiman itu berada di wilayah Kadipaten Herzegovina. Penaklukan Utsmani terjadi pada 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["Masjid Hünkâr di Saraybosna — saksi bertanggal paling awal permukiman", "ad697a7d"], "d": ["Sancak beyi Bosnia İshak Bey, di permukiman Muslim pertama di dataran Saray, membangun sebuah istana untuk dirinya, Masjid Hünkâr atas nama Fâtih Sultan Mehmed, dan sebuah hamam di sampingnya. Masjid itu bertanggal 862 (1458); ini adalah bangunan bertanggal paling awal Saraybosna yang diketahui.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Waqf İshak Bey — inti kota Saraybosna diwakafkan", "0b364229"], "d": ["Dari akta waqf İshak Bey tertanggal Cemâziyelevvel 866 (Februari 1462) dipahami bahwa selain masjid dan hamam, dibangun pula zâviye, mevlevîhâne, imaret, sebuah jembatan di atas Miljacka, Han Kolobara di seberang, bedesten, kervansaray, dan toko-toko. Dokumen ini adalah fondasi waqf kota; permukiman sudah ada sebelumnya.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatarpazarcığı pertama kali tercatat dalam defter akıncı", "3b1c839e"], "d": ["Catatan tertua tentang kota itu mundur hingga tahun 877 (1472): sebuah defter akıncı di Perpustakaan Nasional Sofia mencatat permukiman itu.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banaluka pertama kali disebut dalam instruksi Raja II. Vladislav", "0ebc6288"], "d": ["Nama Banja Luka pertama kali muncul dalam sebuah instruksi tertanggal 6 Februari 1494 dari raja Hongaria-Kroasia II. Vladislav; kawasan itu terikat pada mahkota Hongaria melalui banat Yayçe. Penaklukan Utsmani terjadi pada musim dingin 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["Penduduk Basra menyelesaikan pemindahan ke lokasi Basra masa kini — Basra lama ditinggalkan", "20f96eac"], "d": ["Penduduk, seiring waktu, mulai menetap di Basra masa kini yang mereka anggap lebih aman terhadap serangan Badui dan yang airnya lebih mudah diperoleh; peralihan ke lokasi baru selesai pada tahun 900 (1494-95). Basra lama, yang didirikan pada masa Hz. Ömer, berada sekitar 25 km dari kota masa kini.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giray Han membangun Istana Khan di tepi Çürüksu — fondasi Bahçesaray", "0792497c"], "d": ["Di lembah yang merupakan kawasan berburu dan istirahat musim panas para gubernur Orda Emas dan khan Krimea pertama, I. Mengli Giray Han membangun istana yang kini dikenal sebagai Istana Khan di tepi Çürüksu dan meletakkan fondasi Bahçesaray. Kota berkembang di sekitar istana dan sepanjang lembah Çürüksu yang sempit, menjadi makmur pada akhir abad XVI, dan menjadi pusat Khanat Krimea.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Kazak Zaporozhia mendirikan Sich pertama di pulau Khortytsia", "e6ca0dd9"], "d": ["Pangeran Dmytro Vyshnevetsky mendirikan Sich Zaporozhia pertama di pulau Khortytsia Kecil di Dnieper. Benteng dikepung dan dihancurkan oleh bangsa Tatar Krimea pada 1558; Sich kemudian dipindahkan ke pulau-pulau di selatan. Istilah: «Sich» (bahasa Ukraina Sich) adalah kamp pusat Kazak Zaporozhia di pulau-pulau Dnieper yang dibentengi dengan balok kayu dan parit; ia adalah markas, tempat dewan (Rada), dan pusat kepala tentara terpilih (koshovyi), bukan ibu kota negara.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Sich Bazavluk didirikan", "fcd507ae"], "d": ["Setelah bangsa Tatar menghancurkan Sich Tomakivka, Kazak Zaporozhia mendirikan Sich baru di pulau Bazavluk, di tempat bertemunya cabang-cabang Dnieper Chortomlyk, Pidpilna, dan Skarban. Sich dihancurkan pada 1638 dengan ekspedisi Polandia setelah penumpasan pemberontakan Kazak. Istilah: «Sich» (bahasa Ukraina Sich) adalah kamp pusat Kazak Zaporozhia di pulau-pulau Dnieper yang dibentengi dengan balok kayu dan parit; ia adalah markas, tempat dewan (Rada), dan pusat kepala tentara terpilih (koshovyi), bukan ibu kota negara. Pada tanggal ini «Hetmanat» belum ada (1648); nama Zaporozhia berarti «seberang jeram» dan Sich-Sich berdiri di perbatasan stepa di hilir jeram Dnieper. Tidak ada kekerabatan etnis dengan Kazak Kazakhstan: Kazak Zaporozhia adalah komunitas Slavia Timur (Ukraina) dan Ortodoks; yang sama hanyalah kata «kazak» (pejuang bebas) yang berasal dari bahasa Turki.", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["Sich Mykytyn Rih pertama kali disebut", "61e22abc"], "d": ["Nama Sich keempat yang didirikan di Mykytyn Rih, di tempat Nikopol masa kini, pertama kali muncul pada 1628; pada 1648 direbut oleh Bohdan Khmelnytsky. Ini adalah saksi pertama tempat itu yang diketahui, bukan pendiriannya.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Sich Chortomlyk didirikan", "4b6e8197"], "d": ["Kazak Zaporozhia mendirikan Sich Chortomlyk, yang juga disebut 'Sich Lama', di tanjung tempat Dnieper bertemu sungai Chortomlyk. Sich dihancurkan oleh tentara Rusia pada 25 Mei 1709 karena mereka mendukung Mazepa.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Kharkov didirikan oleh pengungsi Kazak", "288b303c"], "d": ["Di tepi utara stepa liar, di tempat bertemunya sungai Lopan dan Kharkov, para pengungsi Kazak yang datang dari tepi kanan Dnieper mendirikan sebuah permukiman. Kharkov segera menjadi pusat Sloboda Ukraina yang bergantung pada Moskow.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Kazak Zaporozhia mendirikan Sich Oleshky dengan izin khan Krimea", "ed26f29d"], "d": ["Ketika serangan Rusia mengosongkan Sich di Kamenka, Kazak Zaporozhia dengan izin khan Krimea menetap di Oleshky, di tepi kiri sungai Konka, di tanah khanat. Setelah Perjanjian Prut, Kazak Gordiyenko juga bergabung dengan mereka. Khan tidak mengizinkan Sich memiliki tembok dan meriam.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["Sich Oleshky dijarah dan ditinggalkan", "52361709"], "d": ["Kazak Samara yang pro-Rusia menyerbu dan menjarah Sich Oleshky serta membakar barak. Sich tidak didirikan kembali; Kazak kembali ke Kamenka pada 1730 dan pada 1734 bersumpah setia kepada Rusia lalu mendirikan Sich Baru.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Benteng Stavropol didirikan di tepi Volga", "eb087a50"], "d": ["Di Volga Tengah, benteng Stavropol didirikan untuk bangsa Kalmuk yang menerima agama Kristen (Tolyatti masa kini).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nâdir Şah merebut Kandahar dan merobohkan kota lama", "9cc23e6b"], "d": ["Nâdir Şah, penguasa Afşar, merebut Kandahar yang berada di tangan bangsa Afghan Ghilzai setelah pengepungan panjang. Kota dihancurkan dan penduduknya pindah ke Nâdirâbâd yang didirikan di tenggara lokasi lamanya; Kandahar lama tidak pernah menjadi kota lagi.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["Benteng Stavropol didirikan di garis Azak-Mozdok", "7fd9b9f1"], "d": ["Sepuluh benteng dibangun di garis benteng Azak-Mozdok yang didirikan setelah Küçük Kaynarca untuk mengawasi stepa antara Kuban dan Terek; salah satunya adalah Stavropol. Benteng itu kemudian menjadi pusat kegubernuran Kaukasus dan guberniya Stavropol.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Galangan kapal Kherson didirikan di muara Dnieper", "115f2c34"], "d": ["Di muara Dnieper yang beralih ke Rusia setelah Küçük Kaynarca, sebuah galangan kapal didirikan di dekat benteng Aleksandr-şanc yang dibangun pada 1737 dan segera dihancurkan, dan diberi nama Kherson. Kota menjadi pusat kaza pada 1784 dan pusat gubernia pada 1803.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Orang Yunani dari Krimea mendirikan Mariupol di pesisir Azak", "4e3af209"], "d": ["Orang Yunani yang datang dari Krimea mendirikan Mariupol di tempat Kalmius bermuara ke Laut Azak. Kota menjadi pusat kaza yang bergantung pada kegubernuran Yekaterinoslav pada 1784.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Yekaterinoslav dipindahkan ke lokasinya masa kini di tepi Dnieper", "ec361381"], "d": ["Yekaterinoslav, yang didirikan Potemkin pada 1778 di tempat bertemunya sungai Kilçen dan Samara, dipindahkan ke lokasinya masa kini pada 1783 karena letaknya yang tidak sehat.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["Pelabuhan armada Rusia Sevastopol didirikan di teluk Akhtiar", "01058a25"], "d": ["Setelah aneksasi Krimea oleh Rusia pada 1783, teluk tempat desa Tatar Krimea Akhtiar (Akyar) berada dipilih sebagai pelabuhan militer; pelabuhan didirikan tahun berikutnya dan menerima nama Sevastopol. Kota menjadi pelabuhan utama armada Laut Hitam Rusia pada 1804.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Benteng Nikolayev didirikan di muara Bug", "d57e52b9"], "d": ["Atas perintah Knez Potemkin, sebuah benteng didirikan di tempat bertemunya sungai Bug Selatan dan İngul. Pada 1788 sebuah galangan kapal dibuka di sini dan permukiman menjadi salah satu pusat pembuatan kapal armada Laut Hitam.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Permukiman perbatasan, inti Melitopol, didirikan di tepi Molochna", "637d5817"], "d": ["Setelah aneksasi Krimea, sebuah permukiman perbatasan didirikan di tepi sungai Molochna. Permukiman menerima nama Novooleksandrivka pada 1816 dan dijadikan kota dengan nama Melitopol pada 1841.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Novocherkassk, pusat baru Tentara Kazak Don, didirikan", "bf5709fd"], "d": ["Pusat administratif Tentara Kazak Don berpindah dari Çerkask, yang hingga saat itu menjadi pusat, ke Novocherkassk yang didirikan di lokasi Biryuchiy Kut antara sungai Aksay dan Tuzlov.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Vâdî Halfâ dicatat dalam perjalanan Burckhardt ke Nubia", "6efc72ec"], "d": ["Pelancong Swiss J. L. Burckhardt menulis dalam buku hariannya tertanggal 6 Maret 1813 bahwa ia melewati Vâdî Halfâ dan bahwa di sana dilakukan sejumlah perdagangan. Ini adalah saksi bertanggal pertama yang dapat ditemukan.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Dermaga Berdyansk didirikan di pesisir Azak", "908ac3cf"], "d": ["Atas prakarsa Knez Mihail Vorontsov, Berdyansk didirikan di tempat sungai Berda bermuara ke Laut Azak. Permukiman menjadi kota pada 1835 dan pusat kaza pada 1842.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Penduduk Malatya tinggal di kebun Aspuzu — inti Malatya modern", "d1dba159"], "d": ["Markas besar Utsmani melawan tentara Mesir İbrâhim Paşa dipindahkan dari Mezraa ke Malatya pada musim panas 1838. Penduduk Malatya yang tinggal di rumah musim panas mereka di Aspuzu tidak kembali ke rumah musim dingin mereka di kota lama yang rusak setelah kepergian tentara; Aspuzu menjadi inti Malatya modern. Malatya Lama (Battalgazi) mengecil dan terus hidup.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van didirikan di lokasi barunya — kota lama yang hancur ditinggalkan", "6d278578"], "d": ["Van dibebaskan dari pendudukan pada 2 April 1918. Mereka yang kembali, alih-alih memperbaiki Van lama di tepi danau yang hancur selama tahun-tahun perang, mendirikan kota baru sekitar 7 km ke pedalaman dari pantai di lokasi bekas lingkungan Norşen dan Arak lama. Kota lama ditinggalkan.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraş beralih ke Mamluk — naib Aleppo Bilbân et-Tabahî merebutnya kembali dari bangsa Armenia", "03171265"], "d": ["Maraş, yang sejak 1258 berada di tangan Kerajaan Armenia Kilikia, dengan perjanjian Sultan Halil dengan bangsa Armenia pada 1293 untuk waktu singkat beralih ke Mamluk dan setelah mereka mundur kembali jatuh ke tangan Armenia. Pada 697 (1298) naib Mamluk di Aleppo Bilbân et-Tabahî merebut kembali kota itu. Maraş setelah itu tetap menjadi tanah Mamluk hingga bangkitnya Dulkadırlı.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Kekaisaran Bizantium menjadi pembayar upeti Utsmani", "615df998"], "d": ["Setelah kemenangan Çirmen (1371), kaisar Bizantium Ioannes V pada musim dingin 1372 menerima menjadi pembayar upeti Murad I: ia akan membayar upeti tahunan dan menyediakan pasukan bagi ekspedisi sultan. Bizantium sejak tanggal ini hingga 1403 tetap menjadi negara vasal yang terikat pada Utsmani; blokade Yıldırım Bayezid pada 1391 menaikkan upeti. Setelah kekalahan Ankara, perjanjian Gelibolu (1403) dengan Süleyman Çelebi membebaskan Bizantium dari upeti; dengan perjanjian dengan Murad II pada 1424 upeti dimulai kembali.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Yıldırım Bayezid, setelah wafatnya Barquq, memasukkan Besni, Darende, dan Divriği ke tanah Utsmani", "8e57d7e6"], "d": ["Setelah wafatnya Sultan Mamluk Barquq (Juni 1399), ketika urusan administrasi Negara Mamluk kacau, Yıldırım Bayezid turun ke cekungan Efrat dan memasukkan Besni (Behisni), Darende, dan Divriği bersama Malatya ke tanah Utsmani. Sivas sebelum itu diserahkan kepada Utsmani setelah wafatnya Kadı Burhâneddin pada musim panas 1398. Divriği sejak 1391 berada di bawah kekuasaan Mamluk dan merupakan pos terdepan yang terikat pada eyalet Aleppo. Pemerintahan Utsmani di sini tidak berlangsung lama: karena bahaya Timur yang mendekat, Divriği pada 1401 kembali diberikan kepada Mamluk, dan masuknya kota secara pasti ke pemerintahan Utsmani terjadi setelah Marj Dabiq 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni beralih ke Mamluk pada ekspedisi Timur ke Sivas dan Malatya", "4853da9a"], "d": ["Besni, yang direbut Yıldırım Bayezid pada 1398 bersama Sivas, Darende, dan Malatya, pada 1400 ketika Timur merebut Sivas dan Malatya jatuh ke tangan Mamluk. Timur pada 27 September 1400 setelah pengepungan sengit juga merebut Besni; ketika ia menarik diri dari kawasan itu, Besni kembali masuk ke kekuasaan Mamluk dan tetap di Mamluk (kecuali masa peralihan Dulkadırlı) hingga Yavuz Sultan Selim merebutnya pada Agustus 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği diberikan kembali kepada Mamluk karena bahaya Timur", "97196b1f"], "d": ["Divriği, yang diambil Yıldırım Bayezid dari Mamluk pada 1398, ketika Timur mendekati Anatolia pada 1401 ditinggalkan kembali kepada Mamluk. Karena itu setelah Timur menghancurkan Sivas (1400), Divriği tampak di peta berwarna Mamluk; pada bulan-bulan yang sama Bayezid di timur merebut Erzincan dan Kemah, sehingga tanah Mamluk berada di antara tanah Utsmani di barat (Sivas) dan timur laut (Kemah). Divriği baru beralih secara pasti ke Utsmani setelah Marj Dabiq 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Sultan Mamluk Şeyh merebut kembali Antep dan Darende dari Dulkadırlı", "f90c9508"], "d": ["Sultan Mamluk Şeyh, yang khawatir akan persahabatan Dulkadırlı dengan Utsmani, pada 1414 berekspedisi; ia merebut kembali Antep dan Darende yang sebelumnya atas kehendaknya sendiri ia berikan kepada Dulkadırlı.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Dulkadıroğlu Mehmed Bey merebut kembali Darende dan memasukkan Besni ke wilayahnya", "df914dcb"], "d": ["Darende, yang direbut Mamluk pada 1414, direbut kembali oleh Dulkadıroğlu Mehmed Bey pada 1418 dan ia juga memasukkan Besni ke wilayahnya.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Mamluk mengalahkan Dulkadırlı di Antep; Besni kembali ke pemerintahan Mamluk (perkiraan)", "72742430"], "d": ["Tentara Mamluk pada 1436 mengalahkan Dulkadırlı di Antep, Mehmed Bey mundur ke Akdağ. Tahun kembalinya Besni ke Mamluk tidak tertulis dalam sumber; Besni bergabung dengan Dulkadır pada 1418 dan telah kembali ke Mamluk sebelum Şehsuvar Bey mengambilnya dari Mamluk pada 1465. Atlas mengembalikan Besni ke Mamluk bersama kekalahan ini di pusat tetangga Antep (perkiraan yang dinyatakan).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadıroğlu Şehsuvar Bey merebut Besni dari Mamluk (perkiraan)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), yang diangkat Fatih Sultan Mehmed sebagai bey Dulkadır, merebut Besni, Gerger, Birecik, dan Rumkale yang berada di tangan Mamluk; Mamluk dikalahkan di Turnadağı pada musim gugur 1467 dan di dekat Antep pada musim semi 1468.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emîr Yeşbek mengalahkan Şehsuvar Bey; Besni kembali ke pemerintahan Mamluk (perkiraan)", "4d856aee"], "d": ["Pada musim semi 1471 Emîr Yeşbek mengalahkan Şehsuvar Bey di sungai Savron; Mamluk merebut kembali Kadirli dan Kozan. Şehsuvar dihukum mati di Kairo pada 1472, Mamluk mengangkat kembali Şahbudak sebagai bey. Besni pun dengan kembalinya ini masuk ke pemerintahan Mamluk (TDV besni: 'menjelang akhir abad ke-15 kembali jatuh ke tangan Mamluk').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Pasukan Ferdinand menduduki dan membentengi Solnok", "6c8416e6"], "d": ["Ketika Utsmani bersiap mendirikan benteng di Solnok di tepi Tisza, pasukan Ferdinand I mendahului: mereka menduduki Solnok pada pertengahan September 1550 dan benteng dibuat dapat dipertahankan pada pertengahan Oktober. Dengan demikian Solnok, yang termasuk negeri Izabella, jatuh ke tangan Habsburg setahun sebelum beralihnya Transilvania ke Ferdinand; Utsmani merebut benteng itu pada 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Transilvania beralih ke pemerintahan Habsburg: dewan Kolozsvár mengakui pelepasan hak Izabella", "8458a566"], "d": ["Dengan kesepakatan Martinuzzi dengan Ferdinand, Ratu Izabella atas nama raja kecil János Zsigmond menandatangani surat pelepasan yang dipaksakan kepadanya di benteng Szászsebes pada 19 Juni 1551. Dewan Transilvania yang bersidang di Kolozsvár pada 26 Juli mengakui pelepasan ini dan kedaulatan Raja Ferdinand; tentara Habsburg Jenderal Castaldo memasuki Belgrad Transilvania (Gyulafehérvár). Dengan demikian Transilvania yang terikat pada Utsmani beralih ke pemerintahan Habsburg yang akan berlangsung lima tahun.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Pemerintahan Habsburg di Transilvania berakhir: Transilvania kembali menjadi voyvodalık yang terikat Utsmani", "721a482a"], "d": ["Karena János Zsigmond masih kecil, Habsburg dengan perantaraan pastor keturunan Kroasia Martinuzzi (Fráter György) yang diangkat sebagai walinya, pada 1551 mencoba menguasai Transilvania; Belgrad Transilvania (Gyulafehérvár), Kolozsvár, Brassó, dan Segesvár selama lima tahun berada di bawah pemerintahan Habsburg. Utsmani mencegah keadaan ini dan Transilvania kembali menjadi voyvodalık pembayar upeti yang terikat kepadanya. Setelah itu, selama sekitar 150 tahun pada abad ke-16 dan ke-17, Transilvania mempertahankan statusnya yang bertumpu pada otonomi luas dalam urusan dalam negeri dan kesetiaan kepada Istanbul dalam urusan luar negeri.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt, dan Tokaj beralih ke pihak Szapolyai", "587c782d"], "d": ["Setelah kembalinya Izabella dan János Zsigmond ke Transilvania pada 1556, para pendukung Szapolyai pada 1556 mengepung Nagyvárad. Pada 1557 para aristokrat Tisza Hulu merebut benteng-benteng kerajaan terpenting — Várad, Huszt, dan Tokaj; di tangan Ferdinand hanya tersisa Gyula dan Világos. Várad setelah itu menjadi benteng kepangeranan Transilvania dan tetap demikian hingga Utsmani merebutnya pada 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi merebut Szatmár — ujung utara Transilvania beralih ke Habsburg", "2256bb27"], "d": ["Szatmár, yang beralih ke Habsburg pada 1561 dengan berpindahnya pihak Balassa Menyhért, direbut kembali Báthory István dalam serangan mendadak pada musim gugur 1564 dan dimasukkan ke Transilvania. Komandan Habsburg Lazarus von Schwendi melancarkan serangan balasan pada Februari 1565: Tokaj jatuh pada 9 Februari, Szerencs empat hari kemudian, dan Szatmár hampir tanpa perlawanan jatuh ke tangan pasukan kekaisaran.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Pasukan Bocskai merebut Szatmár", "e93b098b"], "d": ["Ketika pemberontakan Bocskai menyebar ke Hongaria timur laut, Gyulaffy merebut Szatmár yang dikepungnya pada 21 Januari 1605. Perdamaian Wina 23 Juni 1606 menyerahkan provinsi Szatmár kepada Bocskai seumur hidup; karena tidak ada pewaris laki-laki, dengan wafatnya Bocskai pada 29 Desember 1606 provinsi itu kembali ke kerajaan.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Wafatnya Bocskai István — provinsi Szatmár kembali ke kerajaan", "3721bb9b"], "d": ["Pangeran Transilvania Bocskai István wafat di Kassa pada 29 Desember 1606. Perdamaian Wina (23 Juni 1606) telah menyerahkan provinsi-provinsi, termasuk Szatmár, kepadanya seumur hidup, untuk kembali ke kerajaan bila tidak ada pewaris laki-laki; dengan ketentuan ini provinsi Szatmár kembali ke kerajaan Hongaria Habsburg. Transilvania mulai mencari pangeran baru.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor menguasai provinsi Szatmár", "80263da1"], "d": ["Dengan ekspedisi Bethlen Gábor ke Hongaria pada musim gugur 1619, provinsi Szatmár masuk ke kendali pangeran Transilvania; pada November 1619 ia menyapa provinsi itu melalui surat. Pra-perjanjian 23 Januari 1620 dan Perdamaian Nikolsburg menyerahkan tujuh provinsi, termasuk Szatmár, kepada Bethlen seumur hidup. Setelah wafatnya Bethlen (15 November 1629), pengembalian provinsi-provinsi kepada kerajaan rampung pada 30 Maret 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Pengembalian tujuh provinsi Bethlen Gábor kepada kerajaan rampung", "31b5968f"], "d": ["Perdamaian Nikolsburg telah menyerahkan tujuh provinsi Hongaria Hulu, termasuk Szatmár, kepada Bethlen Gábor seumur hidup. Setelah wafatnya Bethlen pada 15 November 1629, pengembalian provinsi-provinsi kepada kerajaan dimulai dengan instruksi 30 November 1629 dan rampung pada 30 Maret 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György I Rákóczi menerima penyerahan Szatmár", "f398635b"], "d": ["Pada ekspedisi 1644 pangeran Transilvania György I Rákóczi, garnisun Jerman Szatmár beralih ke dinas Rákóczi dan benteng jatuh ke tangan Transilvania. Perdamaian Linz 16 Desember 1645 menyerahkan benteng itu kepada para pewaris Rákóczi selama seorang Rákóczi duduk di takhta Transilvania.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Hilangnya Nitra — De Souches merebut kembali benteng", "c71bf012"], "d": ["Nitra, yang menyerah dengan perlawanan singkat setelah penaklukan Uyvar pada 1663, dikepung komandan kekaisaran De Souches pada 15 April 1664; benteng menyerah pada 3 Mei 1664. Karena Perjanjian Vasvár meninggalkan tempat-tempat yang direbut sebagaimana adanya, Uyvar tetap di Utsmani sedangkan Nitra tetap di tangan Habsburg.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Hilangnya Léva", "f311920e"], "d": ["De Souches setelah Nitra mengepung Léva pada 9 Juni 1664; pada 13 Juni ditandatangani kapitulasi dan pada 14 Juni benteng berada di tangan pasukan kekaisaran. Pertempuran Léva (Garamszentbenedek) pada 19 Juli 1664 tidak mengubah kepemilikan; hasilnya Habsburg tetap menguasai Léva dan Nitra.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroşenko menyerahkan Chigirin kepada Samoylovych", "3b538237"], "d": ["Hetman tepi kanan di bawah perlindungan Utsmani Petro Doroshenko pada 19 September 1676 menyerahkan ibu kotanya Chigirin kepada hetman tepi kiri Samoylovych dan pasukan Rusia. Utsmani mencopot Doroshenko dan mengangkat Yuri Khmelnytsky sebagai gantinya; pengepungan 1677 untuk mengusir garnisun Rusia di Chigirin gagal, benteng baru direbut pada 21 Agustus 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Penyerahan benteng-benteng Banat Transilvania (Temeşvar, Lippa, Lugos, Karánsebes) kepada Raja Hongaria Ferdinand", "0e354976"], "d": ["Pada 1551 tentara Habsburg di bawah Jenderal Castaldo memasuki Transilvania; Ratu Izabella dan putranya terpaksa melepaskan hak atas takhta Hongaria. Dengan persetujuan Castaldo, pada pertengahan Juli 1551 Martinuzzi mengutus Báthory Endre untuk menerima benteng-benteng Temeşvar, Lippa, Solymos, Karánsebes, Lugos, Becse, Becskerek, dan Çanad atas nama Ferdinand. Benteng-benteng selatan Transilvania yang berada di bawah perlindungan Utsmani pun jatuh ke tangan Habsburg; ekspedisi Kanûnî tahun 1551-1552 adalah jawabannya.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Pengangkatan Petrovics Péter sebagai sancakbeyi Lugos dan Karánsebes", "bcbe73e4"], "d": ["Atas permohonan gigih Izabella dan Petrovics, Kanûnî memutuskan mengembalikan János Zsigmond yang masih kecil ke Transilvania. Dengan surat dari Aleppo pada 7 April 1554, ia memerintahkan agar Transilvania membawa anak itu kembali ke negerinya; ia juga memerintahkan para voyvoda Eflak dan Boğdan membantu Petrovics dalam hal ini, yang pada saat yang sama diangkatnya sebagai sancakbeyi Lugos dan Karánsebes. Lugos, yang ditaklukkan pada 1552, dengan demikian diberikan kepada Petrovics sebagai sebuah sancak Utsmani.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Pengepungan Lippa dicabut — serbuan ban Lugos ke Temeşvar", "be03430e"], "d": ["Pada musim semi 1596 pasha Temeşvar mengepung Lippa. Pada malam yang menghubungkan 10 Mei dengan 11-nya, atas perintah Palatics György, ban Lugos dari Transilvania, prajurit Buday György menyerbu pinggiran Temeşvar dan membakarnya; Borbély György yang menembakkan seluruh meriam di benteng juga meyakinkan sang pasha bahwa bantuan telah datang. Pada 11 Mei pasha mundur dari depan Lippa dan bergegas melindungi pusatnya sendiri. Pada saat itu Lugos berada di tangan Kepangeranan Transilvania.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Pendudukan Orsova oleh pasukan Austria di bawah Veterani", "1b4a4f6c"], "d": ["Dalam ekspedisi 1688, Jenderal Veterani, setelah merebut Karánsebes, bergerak ke Orsova dan menduduki tempat itu juga. Dalam sumber tidak ada hari pendudukan; dipakai dasar tahun, 1 Januari 1688.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Perebutan kembali Orsova oleh Thököly dan pasukan Utsmani", "c5645da9"], "d": ["Setelah Vetislan direbut, Thököly dan para pasha Utsmani bergerak ke Orsova yang diduduki Veterani pada 1688. Setelah pertempuran kecil, Thököly memasuki Orsova pada 15 Juli 1689. Heissler, yang datang karena kabar bahaya, melihat pasukan di hadapannya dilengkapi dengan baik dalam hal amunisi dan kapal, lalu mundur untuk melindungi Transilvania. Serangan Herbeville di depan kota pada Agustus juga tidak mampu merebut kembali Orsova.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Sancak Lugos masuk ke pendudukan Habsburg (1691-1695)", "c8bcd6bd"], "d": ["Sancak Lugos berada di bawah pendudukan Habsburg (Jerman) antara 1691 dan 1695; II. Mustafa merebutnya kembali pada 22 September 1695. Dalam catatan lama, 1689-1695 adalah kekosongan yang dinyatakan; irisan 1691-1695 kini diwarnai sebagai Habsburg, sedangkan 1689-1691 tetap kosong. Tanggal hanya diambil berupa tahun.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Benteng Lugos masuk ke administrasi Habsburg", "6a9d401f"], "d": ["Lugoj, benteng sancak yang bergantung pada eyalet Tımışvar, berada di tangan Utsmani sejak 1695; ia dilepaskan kepada Monarki Habsburg bersama penyerahan pusat eyalet pada akhir pengepungan 1716. Catatan lama menaruh peralihan itu pada dasar tahun, 1 Januari 1716.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Perebutan Orsova oleh tentara Habsburg (ekspedisi 1717)", "7a4faffe"], "d": ["Dalam ekspedisi 1717, Jenderal Splényi tiba di depan Orsova pada 27 Agustus dan merebut kota itu dengan mudah; Orsova, yang tak mampu direbut Mercy pada 1716, dengan demikian jatuh ke tangan Habsburg. Petak-petak tepi Tuna di sekitarnya (termasuk bagian Đerdap di sisi Serbia) bergantung pada titik permukiman terdekat, Orsova, sehingga diwarnai dengan pemiliknya. Tanggal hanya diambil berupa tahun; hari pastinya belum terkonfirmasi.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Peralihan palanka Orsova ke Utsmani — komandan penjaga mundur ke Adakale", "de759b16"], "d": ["Pada awal ekspedisi 1738, komandan Vidin Hacı Mehmed Paşa menyerang tabya Erzsébet di tepi Tuna. Pada sore 8 Mei pasukan sipahi 4-5 ribu orang berbaris dari tepi kiri Tuna ke Orsova dan menyerang palanka Orsova; komandan Austria yang kehilangan sekitar seratus orang mundur ke Orsova Baru, yaitu benteng pulau Adakale. Setelah pertempuran Mehadiye pada Juli, Adakale juga jatuh ke tangan Utsmani pada Agustus 1738; Perjanjian Belgrade 1739 mengakui keadaan itu.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["II. Murad merebut Alacahisar, Niş dan Şehirköy kembali ke Utsmani", "54af926a"], "d": ["Setelah wafatnya Despot Serbia Stefan Lazarević tanpa pewaris (1427), II. Murad bergerak dengan menyatakan dirinya pewaris sah Serbia berdasarkan pernikahan Yıldırım Bayezid dengan putri Serbia, dan merebut Alacahisar (1428). Pada tahun yang sama, setelah wafatnya Lazarević, Utsmani juga merebut kembali benteng Şehirköy — kota itu direbut Stefan pada 1412 dan dipertahankan melawan Mûsâ Çelebi. Menurut artikel TDV nis, Utsmani juga merebut kembali Niş pada tahun yang sama (831/1428). Dengan demikian garis yang menghubungkan lembah Morava Besar dan Nišava masuk ke bawah kendali Utsmani.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Tentara Salib merebut Şehirköy — cabang Nišava dari 'Ekspedisi Panjang'", "fdf6140c"], "d": ["Tentara Salib di bawah pimpinan Raja Vladislav dan Despot Serbia Đurađ Branković merebut Şehirköy pada 1443. Dalam kelanjutan ekspedisi yang sama, pasukan Utsmani akan dikalahkan di celah İzladi pada November. Şehirköy diberikan kembali kepada Serbia oleh II. Murad setelah Perjanjian Segedin (1444), tetapi beralih ke Utsmani setelah wafatnya Đurađ Branković pada 1456.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Kekuasaan Utsmani yang pasti di kawasan Alacahisar terwujud", "9715382a"], "d": ["Alacahisar, yang diserahkan kepada Branković pada akhir perjanjian dengan utusan Hongaria tahun 1444, kembali masuk ke kekuasaan Turki pada tahun-tahun setelah kemenangan Varna. Penaklukan kedua kota ini tidak dibuktikan dengan catatan perang, melainkan catatan keuangan: catatan timar beberapa desa yang bergantung pada Alacahisar bertanggal akhir 1453/awal 1454; tetapi ini hanya kesaksian desa — pada 1454 pasukan Utsmani dikalahkan di sekitar Alacahisar, dan pada 1455 Alacahisar ditinggalkan kepada Branković sebagai perbatasan. Menurut TDV, kekuasaan Utsmani yang pasti di kawasan itu terwujud pada 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Pendirian Despotat Mora — Manuel Kantakuzenos di Mezistre", "87660b82"], "d": ["Kaisar Bizantium Ioannes Kantakuzenos memberikan putranya Manuel sebuah wilayah administratif tersendiri di Mora; Despotat Mora yang berpusat di Mezistre lahir dengan cara ini. Manuel memerintah hingga 1380; pada masa ini budaya dan seni Bizantium berkembang terutama di Mezistre. Despotat bertahan hingga penaklukan Fâtih pada 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Despot Konstantinos merebut Patras dari bangsa Frank", "cb0dd18c"], "d": ["Konstantinos, Despot Mora (kaisar Bizantium terakhir pada 1449), merebut kembali Patras dari bangsa Latin; dengan demikian pelabuhan penting di barat laut semenanjung ini juga bergabung ke despotat. Patras masuk ke kekuasaan Utsmani pada ekspedisi Mora Fâtih tahun 1458.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić-Kosača 'Adipati St. Sava' — lahirnya Hersek", "cc67061f"], "d": ["Stjepan Vukčić-Kosača, yang menyatukan Hum dan Trebinje dalam satu kebeyan, memberontak melawan raja Bosnia dan menyatakan dirinya 'Herzeg (adipati) St. Sava'; gelar itu diberikan oleh Kaisar Friedrich III pada 1448. Nama Herzegovina ('tanah sang Herzeg') berasal dari gelar ini. Hersek beralih sepotong demi sepotong ke Utsmani sejak 1466, menjadi sancak pada 1470; sisa wilayahnya bergabung pada awal 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Perdamaian Kraków — negara ordo Teutonik berubah menjadi Kadipaten Prusia", "78666ddd"], "d": ["Albrecht dari Brandenburg, Grand Master Ksatria Teutonik, yang tidak menemukan bantuan melawan Polandia, menandatangani Perdamaian Kraków. Negara ordo (Ordensstaat) menjadi sebuah kadipaten turun-temurun dan duniawi yang beralih ke dinasti Brandenburg di bawah suzerainitas Polandia. Pusatnya adalah Königsberg; Albrecht mendirikan Universitas Albertus di sana pada 1544. Kadipaten itu berubah menjadi Kerajaan Prusia pada 1701.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proklamasi Republik Austria — akhir monarki Habsburg", "c84f316c"], "d": ["Sehari setelah Kaisar Karl I menarik diri dari urusan negara pada 11 November, Majelis Nasional Sementara mengesahkan undang-undang tentang bentuk negara dan pemerintahan, dan republik diproklamasikan. Republik Pertama yang berpusat di Wina menggantikan Austria Habsburg. Dengan proklamasi ini Wina, Linz, Salzburg, Innsbruck, Klagenfurt, Bregenz, dan kota-kota Jerman-Austria lainnya menjadi wilayah Republik Austria (Deutschösterreich).", "2dcc1399"]}
});
